    // --------------------------------------------------------------------------------
    // Function :
    //   delete([$p_option, $p_option_value, ...])
    // Description :
    //   This method removes files from the archive.
    //   If no parameters are given, then all the archive is emptied.
    // Parameters :
    //   None or optional arguments.
    // Options :
    //   PCLZIP_OPT_BY_INDEX :
    //   PCLZIP_OPT_BY_NAME :
    //   PCLZIP_OPT_BY_EREG :
    //   PCLZIP_OPT_BY_PREG :
    // Return Values :
    //   0 on failure,
    //   The list of the files which are still present in the archive.
    //   (see PclZip::listContent() for list entry format)
    // --------------------------------------------------------------------------------
    public function delete()
    {
        $v_result = 1;
        // ----- Reset the error handler
        $this->priv_error_reset();
        // ----- Check archive
        if (!$this->priv_check_format()) {
            return 0;
        }
        // ----- Set default values
        $v_options = [];
        // ----- Look for variable options arguments
        $v_size = func_num_args();
        // ----- Look for arguments
        if ($v_size > 0) {
            // ----- Get the arguments
            $v_arg_list = func_get_args();
            // ----- Parse the options
            $v_result = $this->priv_parse_options($v_arg_list, $v_size, $v_options, [PCLZIP_OPT_BY_NAME => 'optional', PCLZIP_OPT_BY_EREG => 'optional', PCLZIP_OPT_BY_PREG => 'optional', PCLZIP_OPT_BY_INDEX => 'optional']);
            if ($v_result != 1) {
                return 0;
            }
        }
        // ----- Magic quotes trick
        $this->priv_disable_magic_quotes();
        // ----- Call the delete fct
        $v_list = [];
        if (($v_result = $this->priv_delete_by_rule($v_list, $v_options)) != 1) {
            $this->priv_swap_back_magic_quotes();
            unset($v_list);
            return 0;
        }
        // ----- Magic quotes trick
        $this->priv_swap_back_magic_quotes();
        // ----- Return
        return $v_list;
    }
