    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : properties()
    // Description :
    //   This method gives the properties of the archive.
    //   The properties are :
    //     nb : Number of files in the archive
    //     comment : Comment associated with the archive file
    //     status : not_exist, ok
    // Parameters :
    //   None
    // Return Values :
    //   0 on failure,
    //   An array with the archive properties.
    // --------------------------------------------------------------------------------
    public function properties()
    {
        // ----- Reset the error handler
        $this->priv_error_reset();
        // ----- Magic quotes trick
        $this->priv_disable_magic_quotes();
        // ----- Check archive
        if (!$this->priv_check_format()) {
            $this->priv_swap_back_magic_quotes();
            return 0;
        }
        // ----- Default properties
        $v_prop = [];
        $v_prop['comment'] = '';
        $v_prop['nb'] = 0;
        $v_prop['status'] = 'not_exist';
        // ----- Look if file exists
        if (@is_file($this->zipname)) {
            // ----- Open the zip file
            if (($this->zip_fd = @fopen($this->zipname, 'rb')) == 0) {
                $this->priv_swap_back_magic_quotes();
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open archive \'' . $this->zipname . '\' in binary read mode');
                // ----- Return
                return 0;
            }
            // ----- Read the central directory information
            $v_central_dir = [];
            if (($v_result = $this->priv_read_end_central_dir($v_central_dir)) != 1) {
                $this->priv_swap_back_magic_quotes();
                return 0;
            }
            // ----- Close the zip file
            $this->priv_close_fd();
            // ----- Set the user attributes
            $v_prop['comment'] = $v_central_dir['comment'];
            $v_prop['nb'] = $v_central_dir['entries'];
            $v_prop['status'] = 'ok';
        }
        // ----- Magic quotes trick
        $this->priv_swap_back_magic_quotes();
        // ----- Return
        return $v_prop;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : duplicate()
    // Description :
    //   This method creates an archive by copying the content of an other one. If
    //   the archive already exist, it is replaced by the new one without any warning.
    // Parameters :
    //   $p_archive : The filename of a valid archive, or
    //                a valid PclZip object.
    // Return Values :
    //   1 on success.
    //   0 or a negative value on error (error code).
    // --------------------------------------------------------------------------------
    public function duplicate($p_archive)
    {
        $v_result = 1;
        // ----- Reset the error handler
        $this->priv_error_reset();
        // ----- Look if the $p_archive is an instantiated PclZip object
        if ($p_archive instanceof pclzip) {
            // ----- Duplicate the archive
            $v_result = $this->priv_duplicate($p_archive->zipname);
        } elseif (is_string($p_archive)) {
            // ----- Check that $p_archive is a valid zip file
            // TBC : Should also check the archive format
            if (!is_file($p_archive)) {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_MISSING_FILE, "No file with filename '" . $p_archive . "'");
                $v_result = PCLZIP_ERR_MISSING_FILE;
            } else {
                // ----- Duplicate the archive
                $v_result = $this->priv_duplicate($p_archive);
            }
        } else {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, 'Invalid variable type p_archive_to_add');
            $v_result = PCLZIP_ERR_INVALID_PARAMETER;
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : merge()
    // Description :
    //   This method merge the $p_archive_to_add archive at the end of the current
    //   one ($this).
    //   If the archive ($this) does not exist, the merge becomes a duplicate.
    //   If the $p_archive_to_add archive does not exist, the merge is a success.
    // Parameters :
    //   $p_archive_to_add : It can be directly the filename of a valid zip archive,
    //                       or a PclZip object archive.
    // Return Values :
    //   1 on success,
    //   0 or negative values on error (see below).
    // --------------------------------------------------------------------------------
    public function merge($p_archive_to_add)
    {
        $v_result = 1;
        // ----- Reset the error handler
        $this->priv_error_reset();
        // ----- Check archive
        if (!$this->priv_check_format()) {
            return 0;
        }
        // ----- Look if the $p_archive_to_add is an instantiated PclZip object
        if ($p_archive_to_add instanceof pclzip) {
            // ----- Merge the archive
            $v_result = $this->priv_merge($p_archive_to_add);
        } elseif (is_string($p_archive_to_add)) {
            // ----- Create a temporary archive
            $v_object_archive = new Pcl_Zip($p_archive_to_add);
            // ----- Merge the archive
            $v_result = $this->priv_merge($v_object_archive);
        } else {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, 'Invalid variable type p_archive_to_add');
            $v_result = PCLZIP_ERR_INVALID_PARAMETER;
        }
        // ----- Return
        return $v_result;
    }
