        // ----- Check each file header
        // TBC
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privParseOptions()
    // Description :
    //   This internal methods reads the variable list of arguments ($p_options_list,
    //   $p_size) and generate an array with the options and values ($v_result_list).
    //   $v_requested_options contains the options that can be present and those that
    //   must be present.
    //   $v_requested_options is an array, with the option value as key, and 'optional',
    //   or 'mandatory' as value.
    // Parameters :
    //   See above.
    // Return Values :
    //   1 on success.
    //   0 on failure.
    // --------------------------------------------------------------------------------
    public function priv_parse_options(&$p_options_list, $p_size, array &$v_result_list, $v_requested_options = false)
    {
        $v_result = 1;
        // ----- Read the options
        $i = 0;
        while ($i < $p_size) {
            // ----- Check if the option is supported
            if (!isset($v_requested_options[$p_options_list[$i]])) {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Invalid optional parameter '" . $p_options_list[$i] . "' for this method");
                // ----- Return
                return $this->error_code();
            }
            // ----- Look for next option
            switch ($p_options_list[$i]) {
                // ----- Look for options that request a path value
                case PCLZIP_OPT_PATH:
                case PCLZIP_OPT_REMOVE_PATH:
                case PCLZIP_OPT_ADD_PATH:
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Get the value
                    $v_result_list[$p_options_list[$i]] = pcl_zip_util_translate_win_path($p_options_list[$i + 1], false);
                    $i++;
                    break;
                case PCLZIP_OPT_TEMP_FILE_THRESHOLD:
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        return $this->error_code();
                    }
                    // ----- Check for incompatible options
                    if (isset($v_result_list[PCLZIP_OPT_TEMP_FILE_OFF])) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Option '" . pcl_zip_util_option_text($p_options_list[$i]) . "' can not be used with option 'PCLZIP_OPT_TEMP_FILE_OFF'");
                        return $this->error_code();
                    }
                    // ----- Check the value
                    $v_value = $p_options_list[$i + 1];
                    if (!is_integer($v_value) || $v_value < 0) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_OPTION_VALUE, "Integer expected for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        return $this->error_code();
                    }
                    // ----- Get the value (and convert it in bytes)
                    $v_result_list[$p_options_list[$i]] = $v_value * 1048576;
                    $i++;
                    break;
                case PCLZIP_OPT_TEMP_FILE_ON:
                    // ----- Check for incompatible options
                    if (isset($v_result_list[PCLZIP_OPT_TEMP_FILE_OFF])) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Option '" . pcl_zip_util_option_text($p_options_list[$i]) . "' can not be used with option 'PCLZIP_OPT_TEMP_FILE_OFF'");
                        return $this->error_code();
                    }
                    $v_result_list[$p_options_list[$i]] = true;
                    break;
                case PCLZIP_OPT_TEMP_FILE_OFF:
                    // ----- Check for incompatible options
                    if (isset($v_result_list[PCLZIP_OPT_TEMP_FILE_ON])) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Option '" . pcl_zip_util_option_text($p_options_list[$i]) . "' can not be used with option 'PCLZIP_OPT_TEMP_FILE_ON'");
                        return $this->error_code();
                    }
                    // ----- Check for incompatible options
                    if (isset($v_result_list[PCLZIP_OPT_TEMP_FILE_THRESHOLD])) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Option '" . pcl_zip_util_option_text($p_options_list[$i]) . "' can not be used with option 'PCLZIP_OPT_TEMP_FILE_THRESHOLD'");
                        return $this->error_code();
                    }
                    $v_result_list[$p_options_list[$i]] = true;
                    break;
                case PCLZIP_OPT_EXTRACT_DIR_RESTRICTION:
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Get the value
                    if (is_string($p_options_list[$i + 1]) && $p_options_list[$i + 1] != '') {
                        $v_result_list[$p_options_list[$i]] = pcl_zip_util_translate_win_path($p_options_list[$i + 1], false);
                        $i++;
                    }
                    break;
                // ----- Look for options that request an array of string for value
                case PCLZIP_OPT_BY_NAME:
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Get the value
                    if (is_string($p_options_list[$i + 1])) {
                        $v_result_list[$p_options_list[$i]][0] = $p_options_list[$i + 1];
                    } elseif (is_array($p_options_list[$i + 1])) {
                        $v_result_list[$p_options_list[$i]] = $p_options_list[$i + 1];
                    } else {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_INVALID_OPTION_VALUE, "Wrong parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    $i++;
                    break;
                // ----- Look for options that request an EREG or PREG expression
                case PCLZIP_OPT_BY_EREG:
                    // ereg() is deprecated starting with PHP 5.3. Move PCLZIP_OPT_BY_EREG
                    // to PCLZIP_OPT_BY_PREG
                    $p_options_list[$i] = PCLZIP_OPT_BY_PREG;
                // no break
                case PCLZIP_OPT_BY_PREG:
                // ----- Look for options that takes a string
                case PCLZIP_OPT_COMMENT:
                case PCLZIP_OPT_ADD_COMMENT:
                case PCLZIP_OPT_PREPEND_COMMENT:
                    //case PCLZIP_OPT_CRYPT :
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Get the value
                    if (is_string($p_options_list[$i + 1])) {
                        $v_result_list[$p_options_list[$i]] = $p_options_list[$i + 1];
                    } else {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_INVALID_OPTION_VALUE, "Wrong parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    $i++;
                    break;
                // ----- Look for options that request an array of index
                case PCLZIP_OPT_BY_INDEX:
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Get the value
                    $v_work_list = [];
                    if (is_string($p_options_list[$i + 1])) {
                        // ----- Remove spaces
                        $p_options_list[$i + 1] = strtr($p_options_list[$i + 1], ' ', '');
                        // ----- Parse items
                        $v_work_list = explode(',', $p_options_list[$i + 1]);
                    } elseif (is_integer($p_options_list[$i + 1])) {
                        $v_work_list[0] = $p_options_list[$i + 1] . '-' . $p_options_list[$i + 1];
                    } elseif (is_array($p_options_list[$i + 1])) {
                        $v_work_list = $p_options_list[$i + 1];
                    } else {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_INVALID_OPTION_VALUE, "Value must be integer, string or array for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Reduce the index list
                    // each index item in the list must be a couple with a start and
                    // an end value : [0,3], [5-5], [8-10], ...
                    // ----- Check the format of each item
                    $v_sort_flag = false;
                    $v_sort_value = 0;
                    for ($j = 0; $j < sizeof($v_work_list); $j++) {
                        // ----- Explode the item
                        $v_item_list = explode('-', $v_work_list[$j]);
                        $v_size_item_list = sizeof($v_item_list);
                        // ----- TBC : Here we might check that each item is a
                        // real integer ...
                        // ----- Look for single value
                        if ($v_size_item_list == 1) {
                            // ----- Set the option value
                            $v_result_list[$p_options_list[$i]][$j]['start'] = $v_item_list[0];
                            $v_result_list[$p_options_list[$i]][$j]['end'] = $v_item_list[0];
                        } elseif ($v_size_item_list == 2) {
                            // ----- Set the option value
                            $v_result_list[$p_options_list[$i]][$j]['start'] = $v_item_list[0];
                            $v_result_list[$p_options_list[$i]][$j]['end'] = $v_item_list[1];
                        } else {
                            // ----- Error log
                            $this->priv_error_log(PCLZIP_ERR_INVALID_OPTION_VALUE, "Too many values in index range for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                            // ----- Return
                            return $this->error_code();
                        }
                        // ----- Look for list sort
                        if ($v_result_list[$p_options_list[$i]][$j]['start'] < $v_sort_value) {
                            $v_sort_flag = true;
                            // ----- TBC : An automatic sort should be written ...
                            // ----- Error log
                            $this->priv_error_log(PCLZIP_ERR_INVALID_OPTION_VALUE, "Invalid order of index range for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                            // ----- Return
                            return $this->error_code();
                        }
                        $v_sort_value = $v_result_list[$p_options_list[$i]][$j]['start'];
                    }
                    // ----- Sort the items
                    if ($v_sort_flag) {
                        // TBC : To Be Completed
                    }
                    // ----- Next option
                    $i++;
                    break;
                // ----- Look for options that request no value
                case PCLZIP_OPT_REMOVE_ALL_PATH:
                case PCLZIP_OPT_EXTRACT_AS_STRING:
                case PCLZIP_OPT_NO_COMPRESSION:
                case PCLZIP_OPT_EXTRACT_IN_OUTPUT:
                case PCLZIP_OPT_REPLACE_NEWER:
                case PCLZIP_OPT_STOP_ON_ERROR:
                    $v_result_list[$p_options_list[$i]] = true;
                    break;
                // ----- Look for options that request an octal value
                case PCLZIP_OPT_SET_CHMOD:
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Get the value
                    $v_result_list[$p_options_list[$i]] = $p_options_list[$i + 1];
                    $i++;
                    break;
                // ----- Look for options that request a call-back
                case PCLZIP_CB_PRE_EXTRACT:
                case PCLZIP_CB_POST_EXTRACT:
                case PCLZIP_CB_PRE_ADD:
                case PCLZIP_CB_POST_ADD:
                    /* for future use
                       case PCLZIP_CB_PRE_DELETE :
                       case PCLZIP_CB_POST_DELETE :
                       case PCLZIP_CB_PRE_LIST :
                       case PCLZIP_CB_POST_LIST :
                       */
                    // ----- Check the number of parameters
                    if ($i + 1 >= $p_size) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_MISSING_OPTION_VALUE, "Missing parameter value for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Get the value
                    $v_function_name = $p_options_list[$i + 1];
                    // ----- Check that the value is a valid existing function
                    if (!function_exists($v_function_name)) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_INVALID_OPTION_VALUE, "Function '" . $v_function_name . "()' is not an existing function for option '" . pcl_zip_util_option_text($p_options_list[$i]) . "'");
                        // ----- Return
                        return $this->error_code();
                    }
                    // ----- Set the attribute
                    $v_result_list[$p_options_list[$i]] = $v_function_name;
                    $i++;
                    break;
                default:
                    // ----- Error log
                    $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Unknown parameter '" . $p_options_list[$i] . "'");
                    // ----- Return
                    return $this->error_code();
            }
            // ----- Next options
            $i++;
        }
        // ----- Look for mandatory options
        if ($v_requested_options !== false) {
            for ($key = reset($v_requested_options); $key = key($v_requested_options); $key = next($v_requested_options)) {
                // ----- Look for mandatory option
                if ($v_requested_options[$key] == 'mandatory') {
                    // ----- Look if present
                    if (!isset($v_result_list[$key])) {
                        // ----- Error log
                        $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, 'Missing mandatory parameter ' . pcl_zip_util_option_text($key) . '(' . $key . ')');
                        // ----- Return
                        return $this->error_code();
                    }
                }
            }
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privOptionDefaultThreshold()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_option_default_threshold(&$p_options): int
    {
        $v_result = 1;
        if (isset($p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD]) || isset($p_options[PCLZIP_OPT_TEMP_FILE_OFF])) {
            return $v_result;
        }
        // ----- Get 'memory_limit' configuration value
        $v_memory_limit = ini_get('memory_limit');
        $v_memory_limit = trim($v_memory_limit);
        $v_memory_limit_int = (int) $v_memory_limit;
        $last = strtolower(substr($v_memory_limit, -1));
        if ($last == 'g') {
            //$v_memory_limit_int = $v_memory_limit_int*1024*1024*1024;
            $v_memory_limit_int = $v_memory_limit_int * 1073741824;
        }
        if ($last == 'm') {
            //$v_memory_limit_int = $v_memory_limit_int*1024*1024;
            $v_memory_limit_int = $v_memory_limit_int * 1048576;
        }
        if ($last == 'k') {
            $v_memory_limit_int = $v_memory_limit_int * 1024;
        }
        $p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD] = floor($v_memory_limit_int * PCLZIP_TEMPORARY_FILE_RATIO);
        // ----- Confidence check : No threshold if value lower than 1M
        if ($p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD] < 1048576) {
            unset($p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD]);
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privFileDescrParseAtt()
    // Description :
    // Parameters :
    // Return Values :
    //   1 on success.
    //   0 on failure.
    // --------------------------------------------------------------------------------
    public function priv_file_descr_parse_att(array &$p_file_list, array &$p_filedescr, $v_options, $v_requested_options = false)
    {
        $v_result = 1;
        // ----- For each file in the list check the attributes
        foreach ($p_file_list as $v_key => $v_value) {
            // ----- Check if the option is supported
            if (!isset($v_requested_options[$v_key])) {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Invalid file attribute '" . $v_key . "' for this file");
                // ----- Return
                return $this->error_code();
            }
            // ----- Look for attribute
            switch ($v_key) {
                case PCLZIP_ATT_FILE_NAME:
                    if (!is_string($v_value)) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, 'Invalid type ' . gettype($v_value) . ". String expected for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    $p_filedescr['filename'] = pcl_zip_util_path_reduction($v_value);
                    if ($p_filedescr['filename'] == '') {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, "Invalid empty filename for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    break;
                case PCLZIP_ATT_FILE_NEW_SHORT_NAME:
                    if (!is_string($v_value)) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, 'Invalid type ' . gettype($v_value) . ". String expected for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    $p_filedescr['new_short_name'] = pcl_zip_util_path_reduction($v_value);
                    if ($p_filedescr['new_short_name'] == '') {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, "Invalid empty short filename for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    break;
                case PCLZIP_ATT_FILE_NEW_FULL_NAME:
                    if (!is_string($v_value)) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, 'Invalid type ' . gettype($v_value) . ". String expected for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    $p_filedescr['new_full_name'] = pcl_zip_util_path_reduction($v_value);
                    if ($p_filedescr['new_full_name'] == '') {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, "Invalid empty full filename for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    break;
                // ----- Look for options that takes a string
                case PCLZIP_ATT_FILE_COMMENT:
                    if (!is_string($v_value)) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, 'Invalid type ' . gettype($v_value) . ". String expected for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    $p_filedescr['comment'] = $v_value;
                    break;
                case PCLZIP_ATT_FILE_MTIME:
                    if (!is_integer($v_value)) {
                        $this->priv_error_log(PCLZIP_ERR_INVALID_ATTRIBUTE_VALUE, 'Invalid type ' . gettype($v_value) . ". Integer expected for attribute '" . pcl_zip_util_option_text($v_key) . "'");
                        return $this->error_code();
                    }
                    $p_filedescr['mtime'] = $v_value;
                    break;
                case PCLZIP_ATT_FILE_CONTENT:
                    $p_filedescr['content'] = $v_value;
                    break;
                default:
                    // ----- Error log
                    $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, "Unknown parameter '" . $v_key . "'");
                    // ----- Return
                    return $this->error_code();
            }
            // ----- Look for mandatory options
            if ($v_requested_options !== false) {
                for ($key = reset($v_requested_options); $key = key($v_requested_options); $key = next($v_requested_options)) {
                    // ----- Look for mandatory option
                    if ($v_requested_options[$key] == 'mandatory') {
                        // ----- Look if present
                        if (!isset($p_file_list[$key])) {
                            $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, 'Missing mandatory parameter ' . pcl_zip_util_option_text($key) . '(' . $key . ')');
                            return $this->error_code();
                        }
                    }
                }
            }
            // end foreach
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privFileDescrExpand()
    // Description :
    //   This method look for each item of the list to see if its a file, a folder
    //   or a string to be added as file. For any other type of files (link, other)
    //   just ignore the item.
    //   Then prepare the information that will be stored for that file.
    //   When its a folder, expand the folder with all the files that are in that
    //   folder (recursively).
    // Parameters :
    // Return Values :
    //   1 on success.
    //   0 on failure.
    // --------------------------------------------------------------------------------
    public function priv_file_descr_expand(&$p_filedescr_list, &$p_options)
    {
        $v_result = 1;
        // ----- Create a result list
        $v_result_list = [];
        // ----- Look each entry
        for ($i = 0; $i < sizeof($p_filedescr_list); $i++) {
            // ----- Get filedescr
            $v_descr = $p_filedescr_list[$i];
            // ----- Reduce the filename
            $v_descr['filename'] = pcl_zip_util_translate_win_path($v_descr['filename'], false);
            $v_descr['filename'] = pcl_zip_util_path_reduction($v_descr['filename']);
            // ----- Look for real file or folder
            if (file_exists($v_descr['filename'])) {
                if (@is_file($v_descr['filename'])) {
                    $v_descr['type'] = 'file';
                } elseif (@is_dir($v_descr['filename'])) {
                    $v_descr['type'] = 'folder';
                } else {
                    // skip
                    continue;
                }
            } elseif (isset($v_descr['content'])) {
                $v_descr['type'] = 'virtual_file';
            } else {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_MISSING_FILE, "File '" . $v_descr['filename'] . "' does not exist");
                // ----- Return
                return $this->error_code();
            }
            // ----- Calculate the stored filename
            $this->priv_calculate_stored_filename($v_descr, $p_options);
            // ----- Add the descriptor in result list
            $v_result_list[sizeof($v_result_list)] = $v_descr;
            // ----- Look for folder
            if ($v_descr['type'] == 'folder') {
                // ----- List of items in folder
                $v_dirlist_descr = [];
                $v_dirlist_nb = 0;
                if ($v_folder_handler = @opendir($v_descr['filename'])) {
                    while (($v_item_handler = @readdir($v_folder_handler)) !== false) {
                        // ----- Skip '.' and '..'
                        if ($v_item_handler == '.') {
                            continue;
                        }
                        if ($v_item_handler == '..') {
                            continue;
                        }
                        // ----- Compose the full filename
                        $v_dirlist_descr[$v_dirlist_nb]['filename'] = $v_descr['filename'] . '/' . $v_item_handler;
                        // ----- Look for different stored filename
                        // Because the name of the folder was changed, the name of the
                        // files/sub-folders also change
                        if ($v_descr['stored_filename'] != $v_descr['filename'] && !isset($p_options[PCLZIP_OPT_REMOVE_ALL_PATH])) {
                            if ($v_descr['stored_filename'] != '') {
                                $v_dirlist_descr[$v_dirlist_nb]['new_full_name'] = $v_descr['stored_filename'] . '/' . $v_item_handler;
                            } else {
                                $v_dirlist_descr[$v_dirlist_nb]['new_full_name'] = $v_item_handler;
                            }
                        }
                        $v_dirlist_nb++;
                    }
                    @closedir($v_folder_handler);
                } else {
                    // TBC : unable to open folder in read mode
                }
                // ----- Expand each element of the list
                if ($v_dirlist_nb != 0) {
                    // ----- Expand
                    if (($v_result = $this->priv_file_descr_expand($v_dirlist_descr, $p_options)) != 1) {
                        return $v_result;
                    }
                    // ----- Concat the resulting list
                    $v_result_list = array_merge($v_result_list, $v_dirlist_descr);
                }
                // ----- Free local array
                unset($v_dirlist_descr);
            }
        }
        // ----- Get the result list
        $p_filedescr_list = $v_result_list;
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privCreate()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_create($p_filedescr_list, &$p_result_list, &$p_options)
    {
        $v_result = 1;
        // ----- Magic quotes trick
        $this->priv_disable_magic_quotes();
        // ----- Open the file in write mode
        if (($v_result = $this->priv_open_fd('wb')) != 1) {
            // ----- Return
            return $v_result;
        }
        // ----- Add the list of files
        $v_result = $this->priv_add_list($p_filedescr_list, $p_result_list, $p_options);
        // ----- Close
        $this->priv_close_fd();
        // ----- Magic quotes trick
        $this->priv_swap_back_magic_quotes();
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privAdd()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_add($p_filedescr_list, &$p_result_list, &$p_options)
    {
        $v_result = 1;
        // ----- Look if the archive exists or is empty
        if (!is_file($this->zipname) || filesize($this->zipname) == 0) {
            // ----- Do a create
            $v_result = $this->priv_create($p_filedescr_list, $p_result_list, $p_options);
            // ----- Return
            return $v_result;
        }
        // ----- Magic quotes trick
        $this->priv_disable_magic_quotes();
        // ----- Open the zip file
        if (($v_result = $this->priv_open_fd('rb')) != 1) {
            // ----- Magic quotes trick
            $this->priv_swap_back_magic_quotes();
            // ----- Return
            return $v_result;
        }
        // ----- Read the central directory information
        $v_central_dir = [];
        if (($v_result = $this->priv_read_end_central_dir($v_central_dir)) != 1) {
            $this->priv_close_fd();
            $this->priv_swap_back_magic_quotes();
            return $v_result;
        }
        // ----- Go to beginning of File
        @rewind($this->zip_fd);
        // ----- Creates a temporary file
        $v_zip_temp_name = PCLZIP_TEMPORARY_DIR . uniqid('pclzip-') . '.tmp';
        // ----- Open the temporary file in write mode
        if (($v_zip_temp_fd = @fopen($v_zip_temp_name, 'wb')) == 0) {
            $this->priv_close_fd();
            $this->priv_swap_back_magic_quotes();
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open temporary file \'' . $v_zip_temp_name . '\' in binary write mode');
            // ----- Return
            return $this->error_code();
        }
        // ----- Copy the files from the archive to the temporary file
        // TBC : Here I should better append the file and go back to erase the central dir
        $v_size = $v_central_dir['offset'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = fread($this->zip_fd, $v_read_size);
            @fwrite($v_zip_temp_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Swap the file descriptor
        // Here is a trick : I swap the temporary fd with the zip fd, in order to use
        // the following methods on the temporary fil and not the real archive
        $v_swap = $this->zip_fd;
        $this->zip_fd = $v_zip_temp_fd;
        $v_zip_temp_fd = $v_swap;
        // ----- Add the files
        $v_header_list = [];
        if (($v_result = $this->priv_add_file_list($p_filedescr_list, $v_header_list, $p_options)) != 1) {
            fclose($v_zip_temp_fd);
            $this->priv_close_fd();
            @unlink($v_zip_temp_name);
            $this->priv_swap_back_magic_quotes();
            // ----- Return
            return $v_result;
        }
        // ----- Store the offset of the central dir
        $v_offset = @ftell($this->zip_fd);
        // ----- Copy the block of file headers from the old archive
        $v_size = $v_central_dir['size'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = @fread($v_zip_temp_fd, $v_read_size);
            @fwrite($this->zip_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Create the Central Dir files header
        for ($i = 0, $v_count = 0; $i < sizeof($v_header_list); $i++) {
            // ----- Create the file header
            if ($v_header_list[$i]['status'] == 'ok') {
                if (($v_result = $this->priv_write_central_file_header($v_header_list[$i])) != 1) {
                    fclose($v_zip_temp_fd);
                    $this->priv_close_fd();
                    @unlink($v_zip_temp_name);
                    $this->priv_swap_back_magic_quotes();
                    // ----- Return
                    return $v_result;
                }
                $v_count++;
            }
            // ----- Transform the header to a 'usable' info
            $this->priv_convert_header2file_info($v_header_list[$i], $p_result_list[$i]);
        }
        // ----- Zip file comment
        $v_comment = $v_central_dir['comment'];
        if (isset($p_options[PCLZIP_OPT_COMMENT])) {
            $v_comment = $p_options[PCLZIP_OPT_COMMENT];
        }
        if (isset($p_options[PCLZIP_OPT_ADD_COMMENT])) {
            $v_comment = $v_comment . $p_options[PCLZIP_OPT_ADD_COMMENT];
        }
        if (isset($p_options[PCLZIP_OPT_PREPEND_COMMENT])) {
            $v_comment = $p_options[PCLZIP_OPT_PREPEND_COMMENT] . $v_comment;
        }
        // ----- Calculate the size of the central header
        $v_size = @ftell($this->zip_fd) - $v_offset;
        // ----- Create the central dir footer
        if (($v_result = $this->priv_write_central_header($v_count + $v_central_dir['entries'], $v_size, $v_offset, $v_comment)) != 1) {
            // ----- Reset the file list
            unset($v_header_list);
            $this->priv_swap_back_magic_quotes();
            // ----- Return
            return $v_result;
        }
        // ----- Swap back the file descriptor
        $v_swap = $this->zip_fd;
        $this->zip_fd = $v_zip_temp_fd;
        $v_zip_temp_fd = $v_swap;
        // ----- Close
        $this->priv_close_fd();
        // ----- Close the temporary file
        @fclose($v_zip_temp_fd);
        // ----- Magic quotes trick
        $this->priv_swap_back_magic_quotes();
        // ----- Delete the zip file
        // TBC : I should test the result ...
        @unlink($this->zipname);
        // ----- Rename the temporary file
        // TBC : I should test the result ...
        //@rename($v_zip_temp_name, $this->zipname);
        pcl_zip_util_rename($v_zip_temp_name, $this->zipname);
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privOpenFd()
    // Description :
    // Parameters :
    // --------------------------------------------------------------------------------
    public function priv_open_fd(string $p_mode)
    {
        $v_result = 1;
        // ----- Look if already open
        if ($this->zip_fd != 0) {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Zip file \'' . $this->zipname . '\' already open');
            // ----- Return
            return $this->error_code();
        }
        // ----- Open the zip file
        if (($this->zip_fd = @fopen($this->zipname, $p_mode)) == 0) {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open archive \'' . $this->zipname . '\' in ' . $p_mode . ' mode');
            // ----- Return
            return $this->error_code();
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privCloseFd()
    // Description :
    // Parameters :
    // --------------------------------------------------------------------------------
    public function priv_close_fd(): int
    {
        $v_result = 1;
        if ($this->zip_fd != 0) {
            @fclose($this->zip_fd);
        }
        $this->zip_fd = 0;
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privAddList()
    // Description :
    //   $p_add_dir and $p_remove_dir will give the ability to memorize a path which is
    //   different from the real path of the file. This is useful if you want to have PclTar
    //   running in any directory, and memorize relative path from an other directory.
    // Parameters :
    //   $p_list : An array containing the file or directory names to add in the tar
    //   $p_result_list : list of added files with their properties (specially the status field)
    //   $p_add_dir : Path to add in the filename path archived
    //   $p_remove_dir : Path to remove in the filename path archived
    // Return Values :
    // --------------------------------------------------------------------------------
    //  function privAddList($p_list, &$p_result_list, $p_add_dir, $p_remove_dir, $p_remove_all_dir, &$p_options)
    public function priv_add_list($p_filedescr_list, &$p_result_list, &$p_options)
    {
        $v_result = 1;
        // ----- Add the files
        $v_header_list = [];
        if (($v_result = $this->priv_add_file_list($p_filedescr_list, $v_header_list, $p_options)) != 1) {
            // ----- Return
            return $v_result;
        }
        // ----- Store the offset of the central dir
        $v_offset = @ftell($this->zip_fd);
        // ----- Create the Central Dir files header
        for ($i = 0, $v_count = 0; $i < sizeof($v_header_list); $i++) {
            // ----- Create the file header
            if ($v_header_list[$i]['status'] == 'ok') {
                if (($v_result = $this->priv_write_central_file_header($v_header_list[$i])) != 1) {
                    // ----- Return
                    return $v_result;
                }
                $v_count++;
            }
            // ----- Transform the header to a 'usable' info
            $this->priv_convert_header2file_info($v_header_list[$i], $p_result_list[$i]);
        }
        // ----- Zip file comment
        $v_comment = '';
        if (isset($p_options[PCLZIP_OPT_COMMENT])) {
            $v_comment = $p_options[PCLZIP_OPT_COMMENT];
        }
        // ----- Calculate the size of the central header
        $v_size = @ftell($this->zip_fd) - $v_offset;
        // ----- Create the central dir footer
        if (($v_result = $this->priv_write_central_header($v_count, $v_size, $v_offset, $v_comment)) != 1) {
            // ----- Reset the file list
            unset($v_header_list);
            // ----- Return
            return $v_result;
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privAddFileList()
    // Description :
    // Parameters :
    //   $p_filedescr_list : An array containing the file description
    //                      or directory names to add in the zip
    //   $p_result_list : list of added files with their properties (specially the status field)
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_add_file_list($p_filedescr_list, &$p_result_list, &$p_options)
    {
        $v_result = 1;
        $v_header = [];
        // ----- Recuperate the current number of elt in list
        $v_nb = sizeof($p_result_list);
        // ----- Loop on the files
        for ($j = 0; $j < sizeof($p_filedescr_list) && $v_result == 1; $j++) {
            // ----- Format the filename
            $p_filedescr_list[$j]['filename'] = pcl_zip_util_translate_win_path($p_filedescr_list[$j]['filename'], false);
            // ----- Skip empty file names
            // TBC : Can this be possible ? not checked in DescrParseAtt ?
            if ($p_filedescr_list[$j]['filename'] == '') {
                continue;
            }
            // ----- Check the filename
            if ($p_filedescr_list[$j]['type'] != 'virtual_file' && !file_exists($p_filedescr_list[$j]['filename'])) {
                $this->priv_error_log(PCLZIP_ERR_MISSING_FILE, "File '" . $p_filedescr_list[$j]['filename'] . "' does not exist");
                return $this->error_code();
            }
            // ----- Look if it is a file or a dir with no all path remove option
            // or a dir with all its path removed
            //      if (   (is_file($p_filedescr_list[$j]['filename']))
            //          || (   is_dir($p_filedescr_list[$j]['filename'])
            if ($p_filedescr_list[$j]['type'] == 'file' || $p_filedescr_list[$j]['type'] == 'virtual_file' || $p_filedescr_list[$j]['type'] == 'folder' && (!isset($p_options[PCLZIP_OPT_REMOVE_ALL_PATH]) || !$p_options[PCLZIP_OPT_REMOVE_ALL_PATH])) {
                // ----- Add the file
                $v_result = $this->priv_add_file($p_filedescr_list[$j], $v_header, $p_options);
                if ($v_result != 1) {
                    return $v_result;
                }
                // ----- Store the file infos
                $p_result_list[$v_nb++] = $v_header;
            }
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privAddFile()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_add_file(array $p_filedescr, array &$p_header, &$p_options)
    {
        $v_result = 1;
        // ----- Working variable
        $p_filename = $p_filedescr['filename'];
        // TBC : Already done in the fileAtt check ... ?
        if ($p_filename == '') {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_INVALID_PARAMETER, 'Invalid file list parameter (invalid or empty list)');
            // ----- Return
            return $this->error_code();
        }
        // ----- Look for a stored different filename
        /* TBC : Removed
           if (isset($p_filedescr['stored_filename'])) {
             $v_stored_filename = $p_filedescr['stored_filename'];
           }
           else {
             $v_stored_filename = $p_filedescr['stored_filename'];
           }
           */
        // ----- Set the file properties
        clearstatcache();
        $p_header['version'] = 20;
        $p_header['version_extracted'] = 10;
        $p_header['flag'] = 0;
        $p_header['compression'] = 0;
        $p_header['crc'] = 0;
        $p_header['compressed_size'] = 0;
        $p_header['filename_len'] = strlen($p_filename);
        $p_header['extra_len'] = 0;
        $p_header['disk'] = 0;
        $p_header['internal'] = 0;
        $p_header['offset'] = 0;
        $p_header['filename'] = $p_filename;
        // TBC : Removed    $p_header['stored_filename'] = $v_stored_filename;
        $p_header['stored_filename'] = $p_filedescr['stored_filename'];
        $p_header['extra'] = '';
        $p_header['status'] = 'ok';
        $p_header['index'] = -1;
        // ----- Look for regular file
        if ($p_filedescr['type'] == 'file') {
            $p_header['external'] = 0x0;
            $p_header['size'] = filesize($p_filename);
        } elseif ($p_filedescr['type'] == 'folder') {
            $p_header['external'] = 0x10;
            $p_header['mtime'] = filemtime($p_filename);
            $p_header['size'] = filesize($p_filename);
        } elseif ($p_filedescr['type'] == 'virtual_file') {
            $p_header['external'] = 0x0;
            $p_header['size'] = strlen($p_filedescr['content']);
        }
        // ----- Look for filetime
        if (isset($p_filedescr['mtime'])) {
            $p_header['mtime'] = $p_filedescr['mtime'];
        } elseif ($p_filedescr['type'] == 'virtual_file') {
            $p_header['mtime'] = time();
        } else {
            $p_header['mtime'] = filemtime($p_filename);
        }
        // ------ Look for file comment
        if (isset($p_filedescr['comment'])) {
            $p_header['comment_len'] = strlen($p_filedescr['comment']);
            $p_header['comment'] = $p_filedescr['comment'];
        } else {
            $p_header['comment_len'] = 0;
            $p_header['comment'] = '';
        }
        // ----- Look for pre-add callback
        if (isset($p_options[PCLZIP_CB_PRE_ADD])) {
            // ----- Generate a local information
            $v_local_header = [];
            $this->priv_convert_header2file_info($p_header, $v_local_header);
            // ----- Call the callback
            // Here I do not use call_user_func() because I need to send a reference to the
            // header.
            $v_result = $p_options[PCLZIP_CB_PRE_ADD](PCLZIP_CB_PRE_ADD, $v_local_header);
            if ($v_result == 0) {
                // ----- Change the file status
                $p_header['status'] = 'skipped';
                $v_result = 1;
            }
            // ----- Update the information
            // Only some fields can be modified
            if ($p_header['stored_filename'] != $v_local_header['stored_filename']) {
                $p_header['stored_filename'] = pcl_zip_util_path_reduction($v_local_header['stored_filename']);
            }
        }
        // ----- Look for empty stored filename
        if ($p_header['stored_filename'] == '') {
            $p_header['status'] = 'filtered';
        }
        // ----- Check the path length
        if (strlen($p_header['stored_filename']) > 0xff) {
            $p_header['status'] = 'filename_too_long';
        }
        // ----- Look if no error, or file not skipped
        if ($p_header['status'] == 'ok') {
            // ----- Look for a file
            if ($p_filedescr['type'] == 'file') {
                // ----- Look for using temporary file to zip
                if (!isset($p_options[PCLZIP_OPT_TEMP_FILE_OFF]) && (isset($p_options[PCLZIP_OPT_TEMP_FILE_ON]) || isset($p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD]) && $p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD] <= $p_header['size'])) {
                    $v_result = $this->priv_add_file_using_temp_file($p_filedescr, $p_header, $p_options);
                    if ($v_result < PCLZIP_ERR_NO_ERROR) {
                        return $v_result;
                    }
                } else {
                    // ----- Open the source file
                    if (($v_file = @fopen($p_filename, 'rb')) == 0) {
                        $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, "Unable to open file '{$p_filename}' in binary read mode");
                        return $this->error_code();
                    }
                    // ----- Read the file content
                    if ($p_header['size'] > 0) {
                        $v_content = @fread($v_file, $p_header['size']);
                    } else {
                        $v_content = '';
                    }
                    // ----- Close the file
                    @fclose($v_file);
                    // ----- Calculate the CRC
                    $p_header['crc'] = @crc32($v_content);
                    // ----- Look for no compression
                    if ($p_options[PCLZIP_OPT_NO_COMPRESSION]) {
                        // ----- Set header parameters
                        $p_header['compressed_size'] = $p_header['size'];
                        $p_header['compression'] = 0;
                    } else {
                        // ----- Compress the content
                        $v_content = @gzdeflate($v_content);
                        // ----- Set header parameters
                        $p_header['compressed_size'] = strlen($v_content);
                        $p_header['compression'] = 8;
                    }
                    // ----- Call the header generation
                    if (($v_result = $this->priv_write_file_header($p_header)) != 1) {
                        @fclose($v_file);
                        return $v_result;
                    }
                    // ----- Write the compressed (or not) content
                    @fwrite($this->zip_fd, $v_content, $p_header['compressed_size']);
                }
            } elseif ($p_filedescr['type'] == 'virtual_file') {
                $v_content = $p_filedescr['content'];
                // ----- Calculate the CRC
                $p_header['crc'] = @crc32($v_content);
                // ----- Look for no compression
                if ($p_options[PCLZIP_OPT_NO_COMPRESSION]) {
                    // ----- Set header parameters
                    $p_header['compressed_size'] = $p_header['size'];
                    $p_header['compression'] = 0;
                } else {
                    // ----- Compress the content
                    $v_content = @gzdeflate($v_content);
                    // ----- Set header parameters
                    $p_header['compressed_size'] = strlen($v_content);
                    $p_header['compression'] = 8;
                }
                // ----- Call the header generation
                if (($v_result = $this->priv_write_file_header($p_header)) != 1) {
                    @fclose($v_file);
                    return $v_result;
                }
                // ----- Write the compressed (or not) content
                @fwrite($this->zip_fd, $v_content, $p_header['compressed_size']);
            } elseif ($p_filedescr['type'] == 'folder') {
                // ----- Look for directory last '/'
                if (@substr($p_header['stored_filename'], -1) != '/') {
                    $p_header['stored_filename'] .= '/';
                }
                // ----- Set the file properties
                $p_header['size'] = 0;
                //$p_header['external'] = 0x41FF0010;   // Value for a folder : to be checked
                $p_header['external'] = 0x10;
                // Value for a folder : to be checked
                // ----- Call the header generation
                if (($v_result = $this->priv_write_file_header($p_header)) != 1) {
                    return $v_result;
                }
            }
        }
        // ----- Look for post-add callback
        if (isset($p_options[PCLZIP_CB_POST_ADD])) {
            // ----- Generate a local information
            $v_local_header = [];
            $this->priv_convert_header2file_info($p_header, $v_local_header);
            // ----- Call the callback
            // Here I do not use call_user_func() because I need to send a reference to the
            // header.
            $v_result = $p_options[PCLZIP_CB_POST_ADD](PCLZIP_CB_POST_ADD, $v_local_header);
            if ($v_result == 0) {
                // ----- Ignored
                $v_result = 1;
            }
            // ----- Update the information
            // Nothing can be modified
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privAddFileUsingTempFile()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_add_file_using_temp_file(array $p_filedescr, array &$p_header, &$p_options)
    {
        $v_result = PCLZIP_ERR_NO_ERROR;
        // ----- Working variable
        $p_filename = $p_filedescr['filename'];
        // ----- Open the source file
        if (($v_file = @fopen($p_filename, 'rb')) == 0) {
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, "Unable to open file '{$p_filename}' in binary read mode");
            return $this->error_code();
        }
        // ----- Creates a compressed temporary file
        $v_gzip_temp_name = PCLZIP_TEMPORARY_DIR . uniqid('pclzip-') . '.gz';
        if (($v_file_compressed = @gzopen($v_gzip_temp_name, 'wb')) == 0) {
            fclose($v_file);
            $this->priv_error_log(PCLZIP_ERR_WRITE_OPEN_FAIL, 'Unable to open temporary file \'' . $v_gzip_temp_name . '\' in binary write mode');
            return $this->error_code();
        }
        // ----- Read the file by PCLZIP_READ_BLOCK_SIZE octets blocks
        $v_size = filesize($p_filename);
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = @fread($v_file, $v_read_size);
            //$v_binary_data = pack('a'.$v_read_size, $v_buffer);
            @gzputs($v_file_compressed, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Close the file
        @fclose($v_file);
        @gzclose($v_file_compressed);
        // ----- Check the minimum file size
        if (filesize($v_gzip_temp_name) < 18) {
            $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'gzip temporary file \'' . $v_gzip_temp_name . '\' has invalid filesize - should be minimum 18 bytes');
            return $this->error_code();
        }
        // ----- Extract the compressed attributes
        if (($v_file_compressed = @fopen($v_gzip_temp_name, 'rb')) == 0) {
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open temporary file \'' . $v_gzip_temp_name . '\' in binary read mode');
            return $this->error_code();
        }
        // ----- Read the gzip file header
        $v_binary_data = @fread($v_file_compressed, 10);
        $v_data_header = unpack('a1id1/a1id2/a1cm/a1flag/Vmtime/a1xfl/a1os', $v_binary_data);
        // ----- Check some parameters
        $v_data_header['os'] = bin2hex($v_data_header['os']);
        // ----- Read the gzip file footer
        @fseek($v_file_compressed, filesize($v_gzip_temp_name) - 8);
        $v_binary_data = @fread($v_file_compressed, 8);
        $v_data_footer = unpack('Vcrc/Vcompressed_size', $v_binary_data);
        // ----- Set the attributes
        $p_header['compression'] = ord($v_data_header['cm']);
        //$p_header['mtime'] = $v_data_header['mtime'];
        $p_header['crc'] = $v_data_footer['crc'];
        $p_header['compressed_size'] = filesize($v_gzip_temp_name) - 18;
        // ----- Close the file
        @fclose($v_file_compressed);
        // ----- Call the header generation
        if (($v_result = $this->priv_write_file_header($p_header)) != 1) {
            return $v_result;
        }
        // ----- Add the compressed data
        if (($v_file_compressed = @fopen($v_gzip_temp_name, 'rb')) == 0) {
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open temporary file \'' . $v_gzip_temp_name . '\' in binary read mode');
            return $this->error_code();
        }
        // ----- Read the file by PCLZIP_READ_BLOCK_SIZE octets blocks
        fseek($v_file_compressed, 10);
        $v_size = $p_header['compressed_size'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = @fread($v_file_compressed, $v_read_size);
            //$v_binary_data = pack('a'.$v_read_size, $v_buffer);
            @fwrite($this->zip_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Close the file
        @fclose($v_file_compressed);
        // ----- Unlink the temporary file
        @unlink($v_gzip_temp_name);
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privCalculateStoredFilename()
    // Description :
    //   Based on file descriptor properties and global options, this method
    //   calculate the filename that will be stored in the archive.
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_calculate_stored_filename(array &$p_filedescr, &$p_options): int
    {
        $v_result = 1;
        // ----- Working variables
        $p_filename = $p_filedescr['filename'];
        if (isset($p_options[PCLZIP_OPT_ADD_PATH])) {
            $p_add_dir = $p_options[PCLZIP_OPT_ADD_PATH];
        } else {
            $p_add_dir = '';
        }
        if (isset($p_options[PCLZIP_OPT_REMOVE_PATH])) {
            $p_remove_dir = $p_options[PCLZIP_OPT_REMOVE_PATH];
        } else {
            $p_remove_dir = '';
        }
        if (isset($p_options[PCLZIP_OPT_REMOVE_ALL_PATH])) {
            $p_remove_all_dir = $p_options[PCLZIP_OPT_REMOVE_ALL_PATH];
        } else {
            $p_remove_all_dir = 0;
        }
        // ----- Look for full name change
        if (isset($p_filedescr['new_full_name'])) {
            // ----- Remove drive letter if any
            $v_stored_filename = pcl_zip_util_translate_win_path($p_filedescr['new_full_name']);
        } else {
            // ----- Look for short name change
            // Its when we change just the filename but not the path
            if (isset($p_filedescr['new_short_name'])) {
                $v_path_info = pathinfo($p_filename);
                $v_dir = '';
                if ($v_path_info['dirname'] != '') {
                    $v_dir = $v_path_info['dirname'] . '/';
                }
                $v_stored_filename = $v_dir . $p_filedescr['new_short_name'];
            } else {
                // ----- Calculate the stored filename
                $v_stored_filename = $p_filename;
            }
            // ----- Look for all path to remove
            if ($p_remove_all_dir) {
                $v_stored_filename = basename($p_filename);
            } elseif ($p_remove_dir != '') {
                if (substr($p_remove_dir, -1) != '/') {
                    $p_remove_dir .= '/';
                }
                if (substr($p_filename, 0, 2) == './' || substr($p_remove_dir, 0, 2) == './') {
                    if (substr($p_filename, 0, 2) == './' && substr($p_remove_dir, 0, 2) != './') {
                        $p_remove_dir = './' . $p_remove_dir;
                    }
                    if (substr($p_filename, 0, 2) != './' && substr($p_remove_dir, 0, 2) == './') {
                        $p_remove_dir = substr($p_remove_dir, 2);
                    }
                }
                $v_compare = pcl_zip_util_path_inclusion($p_remove_dir, $v_stored_filename);
                if ($v_compare > 0) {
                    if ($v_compare == 2) {
                        $v_stored_filename = '';
                    } else {
                        $v_stored_filename = substr($v_stored_filename, strlen($p_remove_dir));
                    }
                }
            }
            // ----- Remove drive letter if any
            $v_stored_filename = pcl_zip_util_translate_win_path($v_stored_filename);
            // ----- Look for path to add
            if ($p_add_dir != '') {
                if (substr($p_add_dir, -1) == '/') {
                    $v_stored_filename = $p_add_dir . $v_stored_filename;
                } else {
                    $v_stored_filename = $p_add_dir . '/' . $v_stored_filename;
                }
            }
        }
        // ----- Filename (reduce the path of stored name)
        $v_stored_filename = pcl_zip_util_path_reduction($v_stored_filename);
        $p_filedescr['stored_filename'] = $v_stored_filename;
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privWriteFileHeader()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_write_file_header(array &$p_header): int
    {
        $v_result = 1;
        // ----- Store the offset position of the file
        $p_header['offset'] = ftell($this->zip_fd);
        // ----- Transform UNIX mtime to DOS format mdate/mtime
        $v_date = getdate($p_header['mtime']);
        $v_mtime = ($v_date['hours'] << 11) + ($v_date['minutes'] << 5) + $v_date['seconds'] / 2;
        $v_mdate = ($v_date['year'] - 1980 << 9) + ($v_date['mon'] << 5) + $v_date['mday'];
        // ----- Packed data
        $v_binary_data = pack('VvvvvvVVVvv', 0x4034b50, $p_header['version_extracted'], $p_header['flag'], $p_header['compression'], $v_mtime, $v_mdate, $p_header['crc'], $p_header['compressed_size'], $p_header['size'], strlen($p_header['stored_filename']), $p_header['extra_len']);
        // ----- Write the first 148 bytes of the header in the archive
        fputs($this->zip_fd, $v_binary_data, 30);
        // ----- Write the variable fields
        if (strlen($p_header['stored_filename']) != 0) {
            fputs($this->zip_fd, $p_header['stored_filename'], strlen($p_header['stored_filename']));
        }
        if ($p_header['extra_len'] != 0) {
            fputs($this->zip_fd, $p_header['extra'], $p_header['extra_len']);
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privWriteCentralFileHeader()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_write_central_file_header(array &$p_header): int
    {
        $v_result = 1;
        // TBC
        //for(reset($p_header); $key = key($p_header); next($p_header)) {
        //}
        // ----- Transform UNIX mtime to DOS format mdate/mtime
        $v_date = getdate($p_header['mtime']);
        $v_mtime = ($v_date['hours'] << 11) + ($v_date['minutes'] << 5) + $v_date['seconds'] / 2;
        $v_mdate = ($v_date['year'] - 1980 << 9) + ($v_date['mon'] << 5) + $v_date['mday'];
        // ----- Packed data
        $v_binary_data = pack('VvvvvvvVVVvvvvvVV', 0x2014b50, $p_header['version'], $p_header['version_extracted'], $p_header['flag'], $p_header['compression'], $v_mtime, $v_mdate, $p_header['crc'], $p_header['compressed_size'], $p_header['size'], strlen($p_header['stored_filename']), $p_header['extra_len'], $p_header['comment_len'], $p_header['disk'], $p_header['internal'], $p_header['external'], $p_header['offset']);
        // ----- Write the 42 bytes of the header in the zip file
        fputs($this->zip_fd, $v_binary_data, 46);
        // ----- Write the variable fields
        if (strlen($p_header['stored_filename']) != 0) {
            fputs($this->zip_fd, $p_header['stored_filename'], strlen($p_header['stored_filename']));
        }
        if ($p_header['extra_len'] != 0) {
            fputs($this->zip_fd, $p_header['extra'], $p_header['extra_len']);
        }
        if ($p_header['comment_len'] != 0) {
            fputs($this->zip_fd, $p_header['comment'], $p_header['comment_len']);
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privWriteCentralHeader()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_write_central_header($p_nb_entries, $p_size, $p_offset, $p_comment): int
    {
        $v_result = 1;
        // ----- Packed data
        $v_binary_data = pack('VvvvvVVv', 0x6054b50, 0, 0, $p_nb_entries, $p_nb_entries, $p_size, $p_offset, strlen($p_comment));
        // ----- Write the 22 bytes of the header in the zip file
        fputs($this->zip_fd, $v_binary_data, 22);
        // ----- Write the variable fields
        if (strlen($p_comment) != 0) {
            fputs($this->zip_fd, $p_comment, strlen($p_comment));
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privList()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_list(&$p_list)
    {
        $v_result = 1;
        // ----- Magic quotes trick
        $this->priv_disable_magic_quotes();
        // ----- Open the zip file
        if (($this->zip_fd = @fopen($this->zipname, 'rb')) == 0) {
            // ----- Magic quotes trick
            $this->priv_swap_back_magic_quotes();
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open archive \'' . $this->zipname . '\' in binary read mode');
            // ----- Return
            return $this->error_code();
        }
        // ----- Read the central directory information
        $v_central_dir = [];
        if (($v_result = $this->priv_read_end_central_dir($v_central_dir)) != 1) {
            $this->priv_swap_back_magic_quotes();
            return $v_result;
        }
        // ----- Go to beginning of Central Dir
        @rewind($this->zip_fd);
        if (@fseek($this->zip_fd, $v_central_dir['offset'])) {
            $this->priv_swap_back_magic_quotes();
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_INVALID_ARCHIVE_ZIP, 'Invalid archive size');
            // ----- Return
            return $this->error_code();
        }
        // ----- Read each entry
        for ($i = 0; $i < $v_central_dir['entries']; $i++) {
            // ----- Read the file header
            if (($v_result = $this->priv_read_central_file_header($v_header)) != 1) {
                $this->priv_swap_back_magic_quotes();
                return $v_result;
            }
            $v_header['index'] = $i;
            // ----- Get the only interesting attributes
            $this->priv_convert_header2file_info($v_header, $p_list[$i]);
            unset($v_header);
        }
        // ----- Close the zip file
        $this->priv_close_fd();
        // ----- Magic quotes trick
        $this->priv_swap_back_magic_quotes();
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privConvertHeader2FileInfo()
    // Description :
    //   This function takes the file information from the central directory
    //   entries and extract the interesting parameters that will be given back.
    //   The resulting file infos are set in the array $p_info
    //     $p_info['filename'] : Filename with full path. Given by user (add),
    //                           extracted in the filesystem (extract).
    //     $p_info['stored_filename'] : Stored filename in the archive.
    //     $p_info['size'] = Size of the file.
    //     $p_info['compressed_size'] = Compressed size of the file.
    //     $p_info['mtime'] = Last modification date of the file.
    //     $p_info['comment'] = Comment associated with the file.
    //     $p_info['folder'] = true/false : indicates if the entry is a folder or not.
    //     $p_info['status'] = status of the action on the file.
    //     $p_info['crc'] = CRC of the file content.
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_convert_header2file_info(array $p_header, array &$p_info): int
    {
        $v_result = 1;
        // ----- Get the interesting attributes
        $v_temp_path = pcl_zip_util_path_reduction($p_header['filename']);
        $p_info['filename'] = $v_temp_path;
        $v_temp_path = pcl_zip_util_path_reduction($p_header['stored_filename']);
        $p_info['stored_filename'] = $v_temp_path;
        $p_info['size'] = $p_header['size'];
        $p_info['compressed_size'] = $p_header['compressed_size'];
        $p_info['mtime'] = $p_header['mtime'];
        $p_info['comment'] = $p_header['comment'];
        $p_info['folder'] = ($p_header['external'] & 0x10) == 0x10;
        $p_info['index'] = $p_header['index'];
        $p_info['status'] = $p_header['status'];
        $p_info['crc'] = $p_header['crc'];
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privExtractByRule()
    // Description :
    //   Extract a file or directory depending of rules (by index, by name, ...)
    // Parameters :
    //   $p_file_list : An array where will be placed the properties of each
    //                  extracted file
    //   $p_path : Path to add while writing the extracted files
    //   $p_remove_path : Path to remove (from the file memorized path) while writing the
    //                    extracted files. If the path does not match the file path,
    //                    the file is extracted with its memorized path.
    //                    $p_remove_path does not apply to 'list' mode.
    //                    $p_path and $p_remove_path are commulative.
    // Return Values :
    //   1 on success,0 or less on error (see error code list)
    // --------------------------------------------------------------------------------
    public function priv_extract_by_rule(&$p_file_list, $p_path, ?string $p_remove_path, $p_remove_all_path, &$p_options)
    {
        $v_result = 1;
        // ----- Magic quotes trick
        $this->priv_disable_magic_quotes();
        // ----- Check the path
        if ($p_path == '' || substr($p_path, 0, 1) != '/' && substr($p_path, 0, 3) != '../' && substr($p_path, 1, 2) != ':/') {
            $p_path = './' . $p_path;
        }
        // ----- Reduce the path last (and duplicated) '/'
        if ($p_path != './' && $p_path != '/') {
            // ----- Look for the path end '/'
            while (substr($p_path, -1) == '/') {
                $p_path = substr($p_path, 0, strlen($p_path) - 1);
            }
        }
        // ----- Look for path to remove format (should end by /)
        if ($p_remove_path != '' && substr($p_remove_path, -1) != '/') {
            $p_remove_path .= '/';
        }
        // ----- Open the zip file
        if (($v_result = $this->priv_open_fd('rb')) != 1) {
            $this->priv_swap_back_magic_quotes();
            return $v_result;
        }
        // ----- Read the central directory information
        $v_central_dir = [];
        if (($v_result = $this->priv_read_end_central_dir($v_central_dir)) != 1) {
            // ----- Close the zip file
            $this->priv_close_fd();
            $this->priv_swap_back_magic_quotes();
            return $v_result;
        }
        // ----- Start at beginning of Central Dir
        $v_pos_entry = $v_central_dir['offset'];
        // ----- Read each entry
        $j_start = 0;
        for ($i = 0, $v_nb_extracted = 0; $i < $v_central_dir['entries']; $i++) {
            // ----- Read next Central dir entry
            @rewind($this->zip_fd);
            if (@fseek($this->zip_fd, $v_pos_entry)) {
                // ----- Close the zip file
                $this->priv_close_fd();
                $this->priv_swap_back_magic_quotes();
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_INVALID_ARCHIVE_ZIP, 'Invalid archive size');
                // ----- Return
                return $this->error_code();
            }
            // ----- Read the file header
            $v_header = [];
            if (($v_result = $this->priv_read_central_file_header($v_header)) != 1) {
                // ----- Close the zip file
                $this->priv_close_fd();
                $this->priv_swap_back_magic_quotes();
                return $v_result;
            }
            // ----- Store the index
            $v_header['index'] = $i;
            // ----- Store the file position
            $v_pos_entry = ftell($this->zip_fd);
            // ----- Look for the specific extract rules
            $v_extract = false;
            // ----- Look for extract by name rule
            if (isset($p_options[PCLZIP_OPT_BY_NAME]) && $p_options[PCLZIP_OPT_BY_NAME] != 0) {
                // ----- Look if the filename is in the list
                for ($j = 0; $j < sizeof($p_options[PCLZIP_OPT_BY_NAME]) && !$v_extract; $j++) {
                    // ----- Look for a directory
                    if (substr($p_options[PCLZIP_OPT_BY_NAME][$j], -1) == '/') {
                        // ----- Look if the directory is in the filename path
                        if (strlen($v_header['stored_filename']) > strlen($p_options[PCLZIP_OPT_BY_NAME][$j]) && substr($v_header['stored_filename'], 0, strlen($p_options[PCLZIP_OPT_BY_NAME][$j])) == $p_options[PCLZIP_OPT_BY_NAME][$j]) {
                            $v_extract = true;
                        }
                    } elseif ($v_header['stored_filename'] == $p_options[PCLZIP_OPT_BY_NAME][$j]) {
                        $v_extract = true;
                    }
                }
            } elseif (isset($p_options[PCLZIP_OPT_BY_PREG]) && $p_options[PCLZIP_OPT_BY_PREG] != '') {
                if (preg_match($p_options[PCLZIP_OPT_BY_PREG], $v_header['stored_filename'])) {
                    $v_extract = true;
                }
            } elseif (isset($p_options[PCLZIP_OPT_BY_INDEX]) && $p_options[PCLZIP_OPT_BY_INDEX] != 0) {
                // ----- Look if the index is in the list
                for ($j = $j_start; $j < sizeof($p_options[PCLZIP_OPT_BY_INDEX]) && !$v_extract; $j++) {
                    if ($i >= $p_options[PCLZIP_OPT_BY_INDEX][$j]['start'] && $i <= $p_options[PCLZIP_OPT_BY_INDEX][$j]['end']) {
                        $v_extract = true;
                    }
                    if ($i >= $p_options[PCLZIP_OPT_BY_INDEX][$j]['end']) {
                        $j_start = $j + 1;
                    }
                    if ($p_options[PCLZIP_OPT_BY_INDEX][$j]['start'] > $i) {
                        break;
                    }
                }
            } else {
                $v_extract = true;
            }
            // ----- Check compression method
            if ($v_extract && ($v_header['compression'] != 8 && $v_header['compression'] != 0)) {
                $v_header['status'] = 'unsupported_compression';
                // ----- Look for PCLZIP_OPT_STOP_ON_ERROR
                if (isset($p_options[PCLZIP_OPT_STOP_ON_ERROR]) && $p_options[PCLZIP_OPT_STOP_ON_ERROR] === true) {
                    $this->priv_swap_back_magic_quotes();
                    $this->priv_error_log(PCLZIP_ERR_UNSUPPORTED_COMPRESSION, "Filename '" . $v_header['stored_filename'] . "' is " . 'compressed by an unsupported compression ' . 'method (' . $v_header['compression'] . ') ');
                    return $this->error_code();
                }
            }
            // ----- Check encrypted files
            if ($v_extract && ($v_header['flag'] & 1) == 1) {
                $v_header['status'] = 'unsupported_encryption';
                // ----- Look for PCLZIP_OPT_STOP_ON_ERROR
                if (isset($p_options[PCLZIP_OPT_STOP_ON_ERROR]) && $p_options[PCLZIP_OPT_STOP_ON_ERROR] === true) {
                    $this->priv_swap_back_magic_quotes();
                    $this->priv_error_log(PCLZIP_ERR_UNSUPPORTED_ENCRYPTION, 'Unsupported encryption for ' . " filename '" . $v_header['stored_filename'] . "'");
                    return $this->error_code();
                }
            }
            // ----- Look for real extraction
            if ($v_extract && $v_header['status'] != 'ok') {
                $v_result = $this->priv_convert_header2file_info($v_header, $p_file_list[$v_nb_extracted++]);
                if ($v_result != 1) {
                    $this->priv_close_fd();
                    $this->priv_swap_back_magic_quotes();
                    return $v_result;
                }
                $v_extract = false;
            }
            // ----- Look for real extraction
            if ($v_extract) {
                // ----- Go to the file position
                @rewind($this->zip_fd);
                if (@fseek($this->zip_fd, $v_header['offset'])) {
                    // ----- Close the zip file
                    $this->priv_close_fd();
                    $this->priv_swap_back_magic_quotes();
                    // ----- Error log
                    $this->priv_error_log(PCLZIP_ERR_INVALID_ARCHIVE_ZIP, 'Invalid archive size');
                    // ----- Return
                    return $this->error_code();
                }
                // ----- Look for extraction as string
                if ($p_options[PCLZIP_OPT_EXTRACT_AS_STRING]) {
                    $v_string = '';
                    // ----- Extracting the file
                    $v_result1 = $this->priv_extract_file_as_string($v_header, $v_string, $p_options);
                    if ($v_result1 < 1) {
                        $this->priv_close_fd();
                        $this->priv_swap_back_magic_quotes();
                        return $v_result1;
                    }
                    // ----- Get the only interesting attributes
                    if (($v_result = $this->priv_convert_header2file_info($v_header, $p_file_list[$v_nb_extracted])) != 1) {
                        // ----- Close the zip file
                        $this->priv_close_fd();
                        $this->priv_swap_back_magic_quotes();
                        return $v_result;
                    }
                    // ----- Set the file content
                    $p_file_list[$v_nb_extracted]['content'] = $v_string;
                    // ----- Next extracted file
                    $v_nb_extracted++;
                    // ----- Look for user callback abort
                    if ($v_result1 == 2) {
                        break;
                    }
                } elseif (isset($p_options[PCLZIP_OPT_EXTRACT_IN_OUTPUT]) && $p_options[PCLZIP_OPT_EXTRACT_IN_OUTPUT]) {
                    // ----- Extracting the file in standard output
                    $v_result1 = $this->priv_extract_file_in_output($v_header, $p_options);
                    if ($v_result1 < 1) {
                        $this->priv_close_fd();
                        $this->priv_swap_back_magic_quotes();
                        return $v_result1;
                    }
                    // ----- Get the only interesting attributes
                    if (($v_result = $this->priv_convert_header2file_info($v_header, $p_file_list[$v_nb_extracted++])) != 1) {
                        $this->priv_close_fd();
                        $this->priv_swap_back_magic_quotes();
                        return $v_result;
                    }
                    // ----- Look for user callback abort
                    if ($v_result1 == 2) {
                        break;
                    }
                } else {
                    // ----- Extracting the file
                    $v_result1 = $this->priv_extract_file($v_header, $p_path, $p_remove_path, $p_remove_all_path, $p_options);
                    if ($v_result1 < 1) {
                        $this->priv_close_fd();
                        $this->priv_swap_back_magic_quotes();
                        return $v_result1;
                    }
                    // ----- Get the only interesting attributes
                    if (($v_result = $this->priv_convert_header2file_info($v_header, $p_file_list[$v_nb_extracted++])) != 1) {
                        // ----- Close the zip file
                        $this->priv_close_fd();
                        $this->priv_swap_back_magic_quotes();
                        return $v_result;
                    }
                    // ----- Look for user callback abort
                    if ($v_result1 == 2) {
                        break;
                    }
                }
            }
        }
        // ----- Close the zip file
        $this->priv_close_fd();
        $this->priv_swap_back_magic_quotes();
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privExtractFile()
    // Description :
    // Parameters :
    // Return Values :
    //
    // 1 : ... ?
    // PCLZIP_ERR_USER_ABORTED(2) : User ask for extraction stop in callback
    // --------------------------------------------------------------------------------
    public function priv_extract_file(array &$p_entry, ?string $p_path, $p_remove_path, $p_remove_all_path, &$p_options)
    {
        $v_result = 1;
        // ----- Read the file header
        if (($v_result = $this->priv_read_file_header($v_header)) != 1) {
            // ----- Return
            return $v_result;
        }
        // ----- Check that the file header is coherent with $p_entry info
        if ($this->priv_check_file_headers($v_header, $p_entry) != 1) {
            // TBC
        }
        // ----- Look for all path to remove
        if ($p_remove_all_path == true) {
            // ----- Look for folder entry that not need to be extracted
            if (($p_entry['external'] & 0x10) == 0x10) {
                $p_entry['status'] = 'filtered';
                return $v_result;
            }
            // ----- Get the basename of the path
            $p_entry['filename'] = basename($p_entry['filename']);
        } elseif ($p_remove_path != '') {
            if (pcl_zip_util_path_inclusion($p_remove_path, $p_entry['filename']) == 2) {
                // ----- Change the file status
                $p_entry['status'] = 'filtered';
                // ----- Return
                return $v_result;
            }
            $p_remove_path_size = strlen($p_remove_path);
            if (substr($p_entry['filename'], 0, $p_remove_path_size) == $p_remove_path) {
                // ----- Remove the path
                $p_entry['filename'] = substr($p_entry['filename'], $p_remove_path_size);
            }
        }
        // ----- Add the path
        if ($p_path != '') {
            $p_entry['filename'] = $p_path . '/' . $p_entry['filename'];
        }
        // ----- Check a base_dir_restriction
        if (isset($p_options[PCLZIP_OPT_EXTRACT_DIR_RESTRICTION])) {
            $v_inclusion = pcl_zip_util_path_inclusion($p_options[PCLZIP_OPT_EXTRACT_DIR_RESTRICTION], $p_entry['filename']);
            if ($v_inclusion == 0) {
                $this->priv_error_log(PCLZIP_ERR_DIRECTORY_RESTRICTION, "Filename '" . $p_entry['filename'] . "' is " . 'outside PCLZIP_OPT_EXTRACT_DIR_RESTRICTION');
                return $this->error_code();
            }
        }
        // ----- Look for pre-extract callback
        if (isset($p_options[PCLZIP_CB_PRE_EXTRACT])) {
            // ----- Generate a local information
            $v_local_header = [];
            $this->priv_convert_header2file_info($p_entry, $v_local_header);
            // ----- Call the callback
            // Here I do not use call_user_func() because I need to send a reference to the
            // header.
            $v_result = $p_options[PCLZIP_CB_PRE_EXTRACT](PCLZIP_CB_PRE_EXTRACT, $v_local_header);
            if ($v_result == 0) {
                // ----- Change the file status
                $p_entry['status'] = 'skipped';
                $v_result = 1;
            }
            // ----- Look for abort result
            if ($v_result == 2) {
                // ----- This status is internal and will be changed in 'skipped'
                $p_entry['status'] = 'aborted';
                $v_result = PCLZIP_ERR_USER_ABORTED;
            }
            // ----- Update the information
            // Only some fields can be modified
            $p_entry['filename'] = $v_local_header['filename'];
        }
        // ----- Look if extraction should be done
        if ($p_entry['status'] == 'ok') {
            // ----- Look for specific actions while the file exist
            if (file_exists($p_entry['filename'])) {
                // ----- Look if file is a directory
                if (is_dir($p_entry['filename'])) {
                    // ----- Change the file status
                    $p_entry['status'] = 'already_a_directory';
                    // ----- Look for PCLZIP_OPT_STOP_ON_ERROR
                    // For historical reason first PclZip implementation does not stop
                    // when this kind of error occurs.
                    if (isset($p_options[PCLZIP_OPT_STOP_ON_ERROR]) && $p_options[PCLZIP_OPT_STOP_ON_ERROR] === true) {
                        $this->priv_error_log(PCLZIP_ERR_ALREADY_A_DIRECTORY, "Filename '" . $p_entry['filename'] . "' is " . 'already used by an existing directory');
                        return $this->error_code();
                    }
                } elseif (!is_writeable($p_entry['filename'])) {
                    // ----- Change the file status
                    $p_entry['status'] = 'write_protected';
                    // ----- Look for PCLZIP_OPT_STOP_ON_ERROR
                    // For historical reason first PclZip implementation does not stop
                    // when this kind of error occurs.
                    if (isset($p_options[PCLZIP_OPT_STOP_ON_ERROR]) && $p_options[PCLZIP_OPT_STOP_ON_ERROR] === true) {
                        $this->priv_error_log(PCLZIP_ERR_WRITE_OPEN_FAIL, "Filename '" . $p_entry['filename'] . "' exists " . 'and is write protected');
                        return $this->error_code();
                    }
                } elseif (filemtime($p_entry['filename']) > $p_entry['mtime']) {
                    // ----- Change the file status
                    if (!(isset($p_options[PCLZIP_OPT_REPLACE_NEWER]) && $p_options[PCLZIP_OPT_REPLACE_NEWER] === true)) {
                        $p_entry['status'] = 'newer_exist';
                        // ----- Look for PCLZIP_OPT_STOP_ON_ERROR
                        // For historical reason first PclZip implementation does not stop
                        // when this kind of error occurs.
                        if (isset($p_options[PCLZIP_OPT_STOP_ON_ERROR]) && $p_options[PCLZIP_OPT_STOP_ON_ERROR] === true) {
                            $this->priv_error_log(PCLZIP_ERR_WRITE_OPEN_FAIL, "Newer version of '" . $p_entry['filename'] . "' exists " . 'and option PCLZIP_OPT_REPLACE_NEWER is not selected');
                            return $this->error_code();
                        }
                    }
                }
            } else {
                if (($p_entry['external'] & 0x10) == 0x10 || substr($p_entry['filename'], -1) == '/') {
                    $v_dir_to_check = $p_entry['filename'];
                } elseif (!strstr($p_entry['filename'], '/')) {
                    $v_dir_to_check = '';
                } else {
                    $v_dir_to_check = dirname($p_entry['filename']);
                }
                if (($v_result = $this->priv_dir_check($v_dir_to_check, ($p_entry['external'] & 0x10) == 0x10)) != 1) {
                    // ----- Change the file status
                    $p_entry['status'] = 'path_creation_fail';
                    // ----- Return
                    //return $v_result;
                    $v_result = 1;
                }
            }
        }
        // ----- Look if extraction should be done
        if ($p_entry['status'] == 'ok') {
            // ----- Do the extraction (if not a folder)
            if (!(($p_entry['external'] & 0x10) == 0x10)) {
                // ----- Look for not compressed file
                if ($p_entry['compression'] == 0) {
                    // ----- Opening destination file
                    if (($v_dest_file = @fopen($p_entry['filename'], 'wb')) == 0) {
                        // ----- Change the file status
                        $p_entry['status'] = 'write_error';
                        // ----- Return
                        return $v_result;
                    }
                    // ----- Read the file by PCLZIP_READ_BLOCK_SIZE octets blocks
                    $v_size = $p_entry['compressed_size'];
                    while ($v_size != 0) {
                        $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
                        $v_buffer = @fread($this->zip_fd, $v_read_size);
                        /* Try to speed up the code
                           $v_binary_data = pack('a'.$v_read_size, $v_buffer);
                           @fwrite($v_dest_file, $v_binary_data, $v_read_size);
                           */
                        @fwrite($v_dest_file, $v_buffer, $v_read_size);
                        $v_size -= $v_read_size;
                    }
                    // ----- Closing the destination file
                    fclose($v_dest_file);
                    // ----- Change the file mtime
                    touch($p_entry['filename'], $p_entry['mtime']);
                } else {
                    // ----- TBC
                    // Need to be finished
                    if (($p_entry['flag'] & 1) == 1) {
                        $this->priv_error_log(PCLZIP_ERR_UNSUPPORTED_ENCRYPTION, 'File \'' . $p_entry['filename'] . '\' is encrypted. Encrypted files are not supported.');
                        return $this->error_code();
                    }
                    // ----- Look for using temporary file to unzip
                    if (!isset($p_options[PCLZIP_OPT_TEMP_FILE_OFF]) && (isset($p_options[PCLZIP_OPT_TEMP_FILE_ON]) || isset($p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD]) && $p_options[PCLZIP_OPT_TEMP_FILE_THRESHOLD] <= $p_entry['size'])) {
                        $v_result = $this->priv_extract_file_using_temp_file($p_entry, $p_options);
                        if ($v_result < PCLZIP_ERR_NO_ERROR) {
                            return $v_result;
                        }
                    } else {
                        // ----- Read the compressed file in a buffer (one shot)
                        if ($p_entry['compressed_size'] > 0) {
                            $v_buffer = @fread($this->zip_fd, $p_entry['compressed_size']);
                        } else {
                            $v_buffer = '';
                        }
                        // ----- Decompress the file
                        $v_file_content = @gzinflate($v_buffer);
                        unset($v_buffer);
                        if ($v_file_content === false) {
                            // ----- Change the file status
                            // TBC
                            $p_entry['status'] = 'error';
                            return $v_result;
                        }
                        // ----- Opening destination file
                        if (($v_dest_file = @fopen($p_entry['filename'], 'wb')) == 0) {
                            // ----- Change the file status
                            $p_entry['status'] = 'write_error';
                            return $v_result;
                        }
                        // ----- Write the uncompressed data
                        @fwrite($v_dest_file, $v_file_content, $p_entry['size']);
                        unset($v_file_content);
                        // ----- Closing the destination file
                        @fclose($v_dest_file);
                    }
                    // ----- Change the file mtime
                    @touch($p_entry['filename'], $p_entry['mtime']);
                }
                // ----- Look for chmod option
                if (isset($p_options[PCLZIP_OPT_SET_CHMOD])) {
                    // ----- Change the mode of the file
                    @chmod($p_entry['filename'], $p_options[PCLZIP_OPT_SET_CHMOD]);
                }
            }
        }
        // ----- Change abort status
        if ($p_entry['status'] == 'aborted') {
            $p_entry['status'] = 'skipped';
        } elseif (isset($p_options[PCLZIP_CB_POST_EXTRACT])) {
            // ----- Generate a local information
            $v_local_header = [];
            $this->priv_convert_header2file_info($p_entry, $v_local_header);
            // ----- Call the callback
            // Here I do not use call_user_func() because I need to send a reference to the
            // header.
            $v_result = $p_options[PCLZIP_CB_POST_EXTRACT](PCLZIP_CB_POST_EXTRACT, $v_local_header);
            // ----- Look for abort result
            if ($v_result == 2) {
                $v_result = PCLZIP_ERR_USER_ABORTED;
            }
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privExtractFileUsingTempFile()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_extract_file_using_temp_file(array &$p_entry, &$p_options)
    {
        $v_result = 1;
        // ----- Creates a temporary file
        $v_gzip_temp_name = PCLZIP_TEMPORARY_DIR . uniqid('pclzip-') . '.gz';
        if (($v_dest_file = @fopen($v_gzip_temp_name, 'wb')) == 0) {
            fclose($v_file);
            $this->priv_error_log(PCLZIP_ERR_WRITE_OPEN_FAIL, 'Unable to open temporary file \'' . $v_gzip_temp_name . '\' in binary write mode');
            return $this->error_code();
        }
        // ----- Write gz file format header
        $v_binary_data = pack('va1a1Va1a1', 0x8b1f, Chr($p_entry['compression']), Chr(0x0), time(), Chr(0x0), Chr(3));
        @fwrite($v_dest_file, $v_binary_data, 10);
        // ----- Read the file by PCLZIP_READ_BLOCK_SIZE octets blocks
        $v_size = $p_entry['compressed_size'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = @fread($this->zip_fd, $v_read_size);
            //$v_binary_data = pack('a'.$v_read_size, $v_buffer);
            @fwrite($v_dest_file, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Write gz file format footer
        $v_binary_data = pack('VV', $p_entry['crc'], $p_entry['size']);
        @fwrite($v_dest_file, $v_binary_data, 8);
        // ----- Close the temporary file
        @fclose($v_dest_file);
        // ----- Opening destination file
        if (($v_dest_file = @fopen($p_entry['filename'], 'wb')) == 0) {
            $p_entry['status'] = 'write_error';
            return $v_result;
        }
        // ----- Open the temporary gz file
        if (($v_src_file = @gzopen($v_gzip_temp_name, 'rb')) == 0) {
            @fclose($v_dest_file);
            $p_entry['status'] = 'read_error';
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open temporary file \'' . $v_gzip_temp_name . '\' in binary read mode');
            return $this->error_code();
        }
        // ----- Read the file by PCLZIP_READ_BLOCK_SIZE octets blocks
        $v_size = $p_entry['size'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = @gzread($v_src_file, $v_read_size);
            //$v_binary_data = pack('a'.$v_read_size, $v_buffer);
            @fwrite($v_dest_file, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        @fclose($v_dest_file);
        @gzclose($v_src_file);
        // ----- Delete the temporary file
        @unlink($v_gzip_temp_name);
        // ----- Return
        return $v_result;
    }
