    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privReadFileHeader()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_read_file_header(array &$p_header)
    {
        $v_result = 1;
        // ----- Read the 4 bytes signature
        $v_binary_data = @fread($this->zip_fd, 4);
        $v_data = unpack('Vid', $v_binary_data);
        // ----- Check signature
        if ($v_data['id'] != 0x4034b50) {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Invalid archive structure');
            // ----- Return
            return $this->error_code();
        }
        // ----- Read the first 42 bytes of the header
        $v_binary_data = fread($this->zip_fd, 26);
        // ----- Look for invalid block size
        if (strlen($v_binary_data) != 26) {
            $p_header['filename'] = '';
            $p_header['status'] = 'invalid_header';
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Invalid block size : ' . strlen($v_binary_data));
            // ----- Return
            return $this->error_code();
        }
        // ----- Extract the values
        $v_data = unpack('vversion/vflag/vcompression/vmtime/vmdate/Vcrc/Vcompressed_size/Vsize/vfilename_len/vextra_len', $v_binary_data);
        // ----- Get filename
        $p_header['filename'] = fread($this->zip_fd, $v_data['filename_len']);
        // ----- Get extra_fields
        if ($v_data['extra_len'] != 0) {
            $p_header['extra'] = fread($this->zip_fd, $v_data['extra_len']);
        } else {
            $p_header['extra'] = '';
        }
        // ----- Extract properties
        $p_header['version_extracted'] = $v_data['version'];
        $p_header['compression'] = $v_data['compression'];
        $p_header['size'] = $v_data['size'];
        $p_header['compressed_size'] = $v_data['compressed_size'];
        $p_header['crc'] = $v_data['crc'];
        $p_header['flag'] = $v_data['flag'];
        $p_header['filename_len'] = $v_data['filename_len'];
        // ----- Recuperate date in UNIX format
        $p_header['mdate'] = $v_data['mdate'];
        $p_header['mtime'] = $v_data['mtime'];
        if ($p_header['mdate'] && $p_header['mtime']) {
            // ----- Extract time
            $v_hour = ($p_header['mtime'] & 0xf800) >> 11;
            $v_minute = ($p_header['mtime'] & 0x7e0) >> 5;
            $v_seconde = ($p_header['mtime'] & 0x1f) * 2;
            // ----- Extract date
            $v_year = (($p_header['mdate'] & 0xfe00) >> 9) + 1980;
            $v_month = ($p_header['mdate'] & 0x1e0) >> 5;
            $v_day = $p_header['mdate'] & 0x1f;
            // ----- Get UNIX date format
            $p_header['mtime'] = @mktime($v_hour, $v_minute, $v_seconde, $v_month, $v_day, $v_year);
        } else {
            $p_header['mtime'] = time();
        }
        // TBC
        //for(reset($v_data); $key = key($v_data); next($v_data)) {
        //}
        // ----- Set the stored filename
        $p_header['stored_filename'] = $p_header['filename'];
        // ----- Set the status field
        $p_header['status'] = 'ok';
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privReadCentralFileHeader()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_read_central_file_header(&$p_header)
    {
        $v_result = 1;
        // ----- Read the 4 bytes signature
        $v_binary_data = @fread($this->zip_fd, 4);
        $v_data = unpack('Vid', $v_binary_data);
        // ----- Check signature
        if ($v_data['id'] != 0x2014b50) {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Invalid archive structure');
            // ----- Return
            return $this->error_code();
        }
        // ----- Read the first 42 bytes of the header
        $v_binary_data = fread($this->zip_fd, 42);
        // ----- Look for invalid block size
        if (strlen($v_binary_data) != 42) {
            $p_header['filename'] = '';
            $p_header['status'] = 'invalid_header';
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Invalid block size : ' . strlen($v_binary_data));
            // ----- Return
            return $this->error_code();
        }
        // ----- Extract the values
        $p_header = unpack('vversion/vversion_extracted/vflag/vcompression/vmtime/vmdate/Vcrc/Vcompressed_size/Vsize/vfilename_len/vextra_len/vcomment_len/vdisk/vinternal/Vexternal/Voffset', $v_binary_data);
        // ----- Get filename
        if ($p_header['filename_len'] != 0) {
            $p_header['filename'] = fread($this->zip_fd, $p_header['filename_len']);
        } else {
            $p_header['filename'] = '';
        }
        // ----- Get extra
        if ($p_header['extra_len'] != 0) {
            $p_header['extra'] = fread($this->zip_fd, $p_header['extra_len']);
        } else {
            $p_header['extra'] = '';
        }
        // ----- Get comment
        if ($p_header['comment_len'] != 0) {
            $p_header['comment'] = fread($this->zip_fd, $p_header['comment_len']);
        } else {
            $p_header['comment'] = '';
        }
        // ----- Extract properties
        // ----- Recuperate date in UNIX format
        //if ($p_header['mdate'] && $p_header['mtime'])
        // TBC : bug : this was ignoring time with 0/0/0
        if (1) {
            // ----- Extract time
            $v_hour = ($p_header['mtime'] & 0xf800) >> 11;
            $v_minute = ($p_header['mtime'] & 0x7e0) >> 5;
            $v_seconde = ($p_header['mtime'] & 0x1f) * 2;
            // ----- Extract date
            $v_year = (($p_header['mdate'] & 0xfe00) >> 9) + 1980;
            $v_month = ($p_header['mdate'] & 0x1e0) >> 5;
            $v_day = $p_header['mdate'] & 0x1f;
            // ----- Get UNIX date format
            $p_header['mtime'] = @mktime($v_hour, $v_minute, $v_seconde, $v_month, $v_day, $v_year);
        } else {
            $p_header['mtime'] = time();
        }
        // ----- Set the stored filename
        $p_header['stored_filename'] = $p_header['filename'];
        // ----- Set default status to ok
        $p_header['status'] = 'ok';
        // ----- Look if it is a directory
        if (substr($p_header['filename'], -1) == '/') {
            //$p_header['external'] = 0x41FF0010;
            $p_header['external'] = 0x10;
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privCheckFileHeaders()
    // Description :
    // Parameters :
    // Return Values :
    //   1 on success,
    //   0 on error;
    // --------------------------------------------------------------------------------
    public function priv_check_file_headers(array &$p_local_header, array &$p_central_header): int
    {
        $v_result = 1;
        // ----- Look for flag bit 3
        if (($p_local_header['flag'] & 8) == 8) {
            $p_local_header['size'] = $p_central_header['size'];
            $p_local_header['compressed_size'] = $p_central_header['compressed_size'];
            $p_local_header['crc'] = $p_central_header['crc'];
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privReadEndCentralDir()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_read_end_central_dir(array &$p_central_dir)
    {
        $v_result = 1;
        // ----- Go to the end of the zip file
        $v_size = filesize($this->zipname);
        @fseek($this->zip_fd, $v_size);
        if (@ftell($this->zip_fd) != $v_size) {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Unable to go to the end of the archive \'' . $this->zipname . '\'');
            // ----- Return
            return $this->error_code();
        }
        // ----- First try : look if this is an archive with no commentaries (most of the time)
        // in this case the end of central dir is at 22 bytes of the file end
        $v_found = 0;
        if ($v_size > 26) {
            @fseek($this->zip_fd, $v_size - 22);
            if (($v_pos = @ftell($this->zip_fd)) != $v_size - 22) {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Unable to seek back to the middle of the archive \'' . $this->zipname . '\'');
                // ----- Return
                return $this->error_code();
            }
            // ----- Read for bytes
            $v_binary_data = @fread($this->zip_fd, 4);
            $v_data = @unpack('Vid', $v_binary_data);
            // ----- Check signature
            if ($v_data['id'] == 0x6054b50) {
                $v_found = 1;
            }
            $v_pos = ftell($this->zip_fd);
        }
        // ----- Go back to the maximum possible size of the Central Dir End Record
        if (!$v_found) {
            $v_maximum_size = 65557;
            // 0xFFFF + 22;
            if ($v_maximum_size > $v_size) {
                $v_maximum_size = $v_size;
            }
            @fseek($this->zip_fd, $v_size - $v_maximum_size);
            if (@ftell($this->zip_fd) != $v_size - $v_maximum_size) {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Unable to seek back to the middle of the archive \'' . $this->zipname . '\'');
                // ----- Return
                return $this->error_code();
            }
            // ----- Read byte per byte in order to find the signature
            $v_pos = ftell($this->zip_fd);
            $v_bytes = 0x0;
            while ($v_pos < $v_size) {
                // ----- Read a byte
                $v_byte = @fread($this->zip_fd, 1);
                // -----  Add the byte
                //$v_bytes = ($v_bytes << 8) | Ord($v_byte);
                // Note we mask the old value down such that once shifted we can never end up with more than a 32bit number
                // Otherwise on systems where we have 64bit integers the check below for the magic number will fail.
                $v_bytes = ($v_bytes & 0xffffff) << 8 | Ord($v_byte);
                // ----- Compare the bytes
                if ($v_bytes == 0x504b0506) {
                    $v_pos++;
                    break;
                }
                $v_pos++;
            }
            // ----- Look if not found end of central dir
            if ($v_pos == $v_size) {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Unable to find End of Central Dir Record signature');
                // ----- Return
                return $this->error_code();
            }
        }
        // ----- Read the first 18 bytes of the header
        $v_binary_data = fread($this->zip_fd, 18);
        // ----- Look for invalid block size
        if (strlen($v_binary_data) != 18) {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'Invalid End of Central Dir Record size : ' . strlen($v_binary_data));
            // ----- Return
            return $this->error_code();
        }
        // ----- Extract the values
        $v_data = unpack('vdisk/vdisk_start/vdisk_entries/ventries/Vsize/Voffset/vcomment_size', $v_binary_data);
        // ----- Check the global size
        if ($v_pos + $v_data['comment_size'] + 18 != $v_size) {
            // ----- Removed in release 2.2 see readme file
            // The check of the file size is a little too strict.
            // Some bugs where found when a zip is encrypted/decrypted with 'crypt'.
            // While decrypted, zip has training 0 bytes
            if (0) {
                // ----- Error log
                $this->priv_error_log(PCLZIP_ERR_BAD_FORMAT, 'The central dir is not at the end of the archive.' . ' Some trailing bytes exists after the archive.');
                // ----- Return
                return $this->error_code();
            }
        }
        // ----- Get comment
        if ($v_data['comment_size'] != 0) {
            $p_central_dir['comment'] = fread($this->zip_fd, $v_data['comment_size']);
        } else {
            $p_central_dir['comment'] = '';
        }
        $p_central_dir['entries'] = $v_data['entries'];
        $p_central_dir['disk_entries'] = $v_data['disk_entries'];
        $p_central_dir['offset'] = $v_data['offset'];
        $p_central_dir['size'] = $v_data['size'];
        $p_central_dir['disk'] = $v_data['disk'];
        $p_central_dir['disk_start'] = $v_data['disk_start'];
        // TBC
        //for(reset($p_central_dir); $key = key($p_central_dir); next($p_central_dir)) {
        //}
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privDeleteByRule()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_delete_by_rule(&$p_result_list, &$p_options)
    {
        $v_result = 1;
        // ----- Open the zip file
        if (($v_result = $this->priv_open_fd('rb')) != 1) {
            // ----- Return
            return $v_result;
        }
        // ----- Read the central directory information
        $v_central_dir = [];
        if (($v_result = $this->priv_read_end_central_dir($v_central_dir)) != 1) {
            $this->priv_close_fd();
            return $v_result;
        }
        // ----- Go to beginning of File
        @rewind($this->zip_fd);
        // ----- Scan all the files
        // ----- Start at beginning of Central Dir
        $v_pos_entry = $v_central_dir['offset'];
        @rewind($this->zip_fd);
        if (@fseek($this->zip_fd, $v_pos_entry)) {
            // ----- Close the zip file
            $this->priv_close_fd();
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_INVALID_ARCHIVE_ZIP, 'Invalid archive size');
            // ----- Return
            return $this->error_code();
        }
        // ----- Read each entry
        $v_header_list = [];
        $j_start = 0;
        for ($i = 0, $v_nb_extracted = 0; $i < $v_central_dir['entries']; $i++) {
            // ----- Read the file header
            $v_header_list[$v_nb_extracted] = [];
            if (($v_result = $this->priv_read_central_file_header($v_header_list[$v_nb_extracted])) != 1) {
                // ----- Close the zip file
                $this->priv_close_fd();
                return $v_result;
            }
            // ----- Store the index
            $v_header_list[$v_nb_extracted]['index'] = $i;
            // ----- Look for the specific extract rules
            $v_found = false;
            // ----- Look for extract by name rule
            if (isset($p_options[PCLZIP_OPT_BY_NAME]) && $p_options[PCLZIP_OPT_BY_NAME] != 0) {
                // ----- Look if the filename is in the list
                for ($j = 0; $j < sizeof($p_options[PCLZIP_OPT_BY_NAME]) && !$v_found; $j++) {
                    // ----- Look for a directory
                    if (substr($p_options[PCLZIP_OPT_BY_NAME][$j], -1) == '/') {
                        // ----- Look if the directory is in the filename path
                        if (strlen($v_header_list[$v_nb_extracted]['stored_filename']) > strlen($p_options[PCLZIP_OPT_BY_NAME][$j]) && substr($v_header_list[$v_nb_extracted]['stored_filename'], 0, strlen($p_options[PCLZIP_OPT_BY_NAME][$j])) == $p_options[PCLZIP_OPT_BY_NAME][$j]) {
                            $v_found = true;
                        } elseif (($v_header_list[$v_nb_extracted]['external'] & 0x10) == 0x10 && $v_header_list[$v_nb_extracted]['stored_filename'] . '/' == $p_options[PCLZIP_OPT_BY_NAME][$j]) {
                            $v_found = true;
                        }
                    } elseif ($v_header_list[$v_nb_extracted]['stored_filename'] == $p_options[PCLZIP_OPT_BY_NAME][$j]) {
                        $v_found = true;
                    }
                }
            } elseif (isset($p_options[PCLZIP_OPT_BY_PREG]) && $p_options[PCLZIP_OPT_BY_PREG] != '') {
                if (preg_match($p_options[PCLZIP_OPT_BY_PREG], $v_header_list[$v_nb_extracted]['stored_filename'])) {
                    $v_found = true;
                }
            } elseif (isset($p_options[PCLZIP_OPT_BY_INDEX]) && $p_options[PCLZIP_OPT_BY_INDEX] != 0) {
                // ----- Look if the index is in the list
                for ($j = $j_start; $j < sizeof($p_options[PCLZIP_OPT_BY_INDEX]) && !$v_found; $j++) {
                    if ($i >= $p_options[PCLZIP_OPT_BY_INDEX][$j]['start'] && $i <= $p_options[PCLZIP_OPT_BY_INDEX][$j]['end']) {
                        $v_found = true;
                    }
                    if ($i >= $p_options[PCLZIP_OPT_BY_INDEX][$j]['end']) {
                        $j_start = $j + 1;
                    }
                    if ($p_options[PCLZIP_OPT_BY_INDEX][$j]['start'] > $i) {
                        break;
                    }
                }
            } else {
                $v_found = true;
            }
            // ----- Look for deletion
            if ($v_found) {
                unset($v_header_list[$v_nb_extracted]);
            } else {
                $v_nb_extracted++;
            }
        }
        // ----- Look if something need to be deleted
        if ($v_nb_extracted > 0) {
            // ----- Creates a temporary file
            $v_zip_temp_name = PCLZIP_TEMPORARY_DIR . uniqid('pclzip-') . '.tmp';
            // ----- Creates a temporary zip archive
            $v_temp_zip = new Pcl_Zip($v_zip_temp_name);
            // ----- Open the temporary zip file in write mode
            if (($v_result = $v_temp_zip->priv_open_fd('wb')) != 1) {
                $this->priv_close_fd();
                // ----- Return
                return $v_result;
            }
            // ----- Look which file need to be kept
            for ($i = 0; $i < sizeof($v_header_list); $i++) {
                // ----- Calculate the position of the header
                @rewind($this->zip_fd);
                if (@fseek($this->zip_fd, $v_header_list[$i]['offset'])) {
                    // ----- Close the zip file
                    $this->priv_close_fd();
                    $v_temp_zip->priv_close_fd();
                    @unlink($v_zip_temp_name);
                    // ----- Error log
                    $this->priv_error_log(PCLZIP_ERR_INVALID_ARCHIVE_ZIP, 'Invalid archive size');
                    // ----- Return
                    return $this->error_code();
                }
                // ----- Read the file header
                $v_local_header = [];
                if (($v_result = $this->priv_read_file_header($v_local_header)) != 1) {
                    // ----- Close the zip file
                    $this->priv_close_fd();
                    $v_temp_zip->priv_close_fd();
                    @unlink($v_zip_temp_name);
                    // ----- Return
                    return $v_result;
                }
                // ----- Check that local file header is same as central file header
                if ($this->priv_check_file_headers($v_local_header, $v_header_list[$i]) != 1) {
                    // TBC
                }
                unset($v_local_header);
                // ----- Write the file header
                if (($v_result = $v_temp_zip->priv_write_file_header($v_header_list[$i])) != 1) {
                    // ----- Close the zip file
                    $this->priv_close_fd();
                    $v_temp_zip->priv_close_fd();
                    @unlink($v_zip_temp_name);
                    // ----- Return
                    return $v_result;
                }
                // ----- Read/write the data block
                if (($v_result = pcl_zip_util_copy_block($this->zip_fd, $v_temp_zip->zip_fd, $v_header_list[$i]['compressed_size'])) != 1) {
                    // ----- Close the zip file
                    $this->priv_close_fd();
                    $v_temp_zip->priv_close_fd();
                    @unlink($v_zip_temp_name);
                    // ----- Return
                    return $v_result;
                }
            }
            // ----- Store the offset of the central dir
            $v_offset = @ftell($v_temp_zip->zip_fd);
            // ----- Re-Create the Central Dir files header
            for ($i = 0; $i < sizeof($v_header_list); $i++) {
                // ----- Create the file header
                if (($v_result = $v_temp_zip->priv_write_central_file_header($v_header_list[$i])) != 1) {
                    $v_temp_zip->priv_close_fd();
                    $this->priv_close_fd();
                    @unlink($v_zip_temp_name);
                    // ----- Return
                    return $v_result;
                }
                // ----- Transform the header to a 'usable' info
                $v_temp_zip->priv_convert_header2file_info($v_header_list[$i], $p_result_list[$i]);
            }
            // ----- Zip file comment
            $v_comment = '';
            if (isset($p_options[PCLZIP_OPT_COMMENT])) {
                $v_comment = $p_options[PCLZIP_OPT_COMMENT];
            }
            // ----- Calculate the size of the central header
            $v_size = @ftell($v_temp_zip->zip_fd) - $v_offset;
            // ----- Create the central dir footer
            if (($v_result = $v_temp_zip->priv_write_central_header(sizeof($v_header_list), $v_size, $v_offset, $v_comment)) != 1) {
                // ----- Reset the file list
                unset($v_header_list);
                $v_temp_zip->priv_close_fd();
                $this->priv_close_fd();
                @unlink($v_zip_temp_name);
                // ----- Return
                return $v_result;
            }
            // ----- Close
            $v_temp_zip->priv_close_fd();
            $this->priv_close_fd();
            // ----- Delete the zip file
            // TBC : I should test the result ...
            @unlink($this->zipname);
            // ----- Rename the temporary file
            // TBC : I should test the result ...
            //@rename($v_zip_temp_name, $this->zipname);
            pcl_zip_util_rename($v_zip_temp_name, $this->zipname);
            // ----- Destroy the temporary archive
            unset($v_temp_zip);
        } elseif ($v_central_dir['entries'] != 0) {
            $this->priv_close_fd();
            if (($v_result = $this->priv_open_fd('wb')) != 1) {
                return $v_result;
            }
            if (($v_result = $this->priv_write_central_header(0, 0, 0, '')) != 1) {
                return $v_result;
            }
            $this->priv_close_fd();
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privDirCheck()
    // Description :
    //   Check if a directory exists, if not it creates it and all the parents directory
    //   which may be useful.
    // Parameters :
    //   $p_dir : Directory path to check.
    // Return Values :
    //    1 : OK
    //   -1 : Unable to create directory
    // --------------------------------------------------------------------------------
    public function priv_dir_check($p_dir, $p_is_dir = false)
    {
        $v_result = 1;
        // ----- Remove the final '/'
        if ($p_is_dir && substr($p_dir, -1) == '/') {
            $p_dir = substr($p_dir, 0, strlen($p_dir) - 1);
        }
        // ----- Check the directory availability
        if (is_dir($p_dir) || $p_dir == '') {
            return 1;
        }
        // ----- Extract parent directory
        $p_parent_dir = dirname($p_dir);
        // ----- Just a check
        if ($p_parent_dir != $p_dir) {
            // ----- Look for parent directory
            if ($p_parent_dir != '') {
                if (($v_result = $this->priv_dir_check($p_parent_dir)) != 1) {
                    return $v_result;
                }
            }
        }
        // ----- Create the directory
        if (!@mkdir($p_dir, 0777)) {
            // ----- Error log
            $this->priv_error_log(PCLZIP_ERR_DIR_CREATE_FAIL, "Unable to create directory '{$p_dir}'");
            // ----- Return
            return $this->error_code();
        }
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privMerge()
    // Description :
    //   If $p_archive_to_add does not exist, the function exit with a success result.
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_merge(&$p_archive_to_add)
    {
        $v_result = 1;
        // ----- Look if the archive_to_add exists
        if (!is_file($p_archive_to_add->zipname)) {
            // ----- Nothing to merge, so merge is a success
            $v_result = 1;
            // ----- Return
            return $v_result;
        }
        // ----- Look if the archive exists
        if (!is_file($this->zipname)) {
            // ----- Do a duplicate
            $v_result = $this->priv_duplicate($p_archive_to_add->zipname);
            // ----- Return
            return $v_result;
        }
        // ----- Open the zip file
        if (($v_result = $this->priv_open_fd('rb')) != 1) {
            // ----- Return
            return $v_result;
        }
        // ----- Read the central directory information
        $v_central_dir = [];
        if (($v_result = $this->priv_read_end_central_dir($v_central_dir)) != 1) {
            $this->priv_close_fd();
            return $v_result;
        }
        // ----- Go to beginning of File
        @rewind($this->zip_fd);
        // ----- Open the archive_to_add file
        if (($v_result = $p_archive_to_add->priv_open_fd('rb')) != 1) {
            $this->priv_close_fd();
            // ----- Return
            return $v_result;
        }
        // ----- Read the central directory information
        $v_central_dir_to_add = [];
        if (($v_result = $p_archive_to_add->priv_read_end_central_dir($v_central_dir_to_add)) != 1) {
            $this->priv_close_fd();
            $p_archive_to_add->priv_close_fd();
            return $v_result;
        }
        // ----- Go to beginning of File
        @rewind($p_archive_to_add->zip_fd);
        // ----- Creates a temporary file
        $v_zip_temp_name = PCLZIP_TEMPORARY_DIR . uniqid('pclzip-') . '.tmp';
        // ----- Open the temporary file in write mode
        if (($v_zip_temp_fd = @fopen($v_zip_temp_name, 'wb')) == 0) {
            $this->priv_close_fd();
            $p_archive_to_add->priv_close_fd();
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open temporary file \'' . $v_zip_temp_name . '\' in binary write mode');
            // ----- Return
            return $this->error_code();
        }
        // ----- Copy the files from the archive to the temporary file
        // TBC : Here I should better append the file and go back to erase the central dir
        $v_size = $v_central_dir['offset'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = fread($this->zip_fd, $v_read_size);
            @fwrite($v_zip_temp_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Copy the files from the archive_to_add into the temporary file
        $v_size = $v_central_dir_to_add['offset'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = fread($p_archive_to_add->zip_fd, $v_read_size);
            @fwrite($v_zip_temp_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Store the offset of the central dir
        $v_offset = @ftell($v_zip_temp_fd);
        // ----- Copy the block of file headers from the old archive
        $v_size = $v_central_dir['size'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = @fread($this->zip_fd, $v_read_size);
            @fwrite($v_zip_temp_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Copy the block of file headers from the archive_to_add
        $v_size = $v_central_dir_to_add['size'];
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = @fread($p_archive_to_add->zip_fd, $v_read_size);
            @fwrite($v_zip_temp_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Merge the file comments
        $v_comment = $v_central_dir['comment'] . ' ' . $v_central_dir_to_add['comment'];
        // ----- Calculate the size of the (new) central header
        $v_size = @ftell($v_zip_temp_fd) - $v_offset;
        // ----- Swap the file descriptor
        // Here is a trick : I swap the temporary fd with the zip fd, in order to use
        // the following methods on the temporary fil and not the real archive fd
        $v_swap = $this->zip_fd;
        $this->zip_fd = $v_zip_temp_fd;
        $v_zip_temp_fd = $v_swap;
        // ----- Create the central dir footer
        if (($v_result = $this->priv_write_central_header($v_central_dir['entries'] + $v_central_dir_to_add['entries'], $v_size, $v_offset, $v_comment)) != 1) {
            $this->priv_close_fd();
            $p_archive_to_add->priv_close_fd();
            @fclose($v_zip_temp_fd);
            $this->zip_fd = null;
            // ----- Reset the file list
            unset($v_header_list);
            // ----- Return
            return $v_result;
        }
        // ----- Swap back the file descriptor
        $v_swap = $this->zip_fd;
        $this->zip_fd = $v_zip_temp_fd;
        $v_zip_temp_fd = $v_swap;
        // ----- Close
        $this->priv_close_fd();
        $p_archive_to_add->priv_close_fd();
        // ----- Close the temporary file
        @fclose($v_zip_temp_fd);
        // ----- Delete the zip file
        // TBC : I should test the result ...
        @unlink($this->zipname);
        // ----- Rename the temporary file
        // TBC : I should test the result ...
        //@rename($v_zip_temp_name, $this->zipname);
        pcl_zip_util_rename($v_zip_temp_name, $this->zipname);
        // ----- Return
        return $v_result;
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privDuplicate()
    // Description :
    // Parameters :
    // Return Values :
    // --------------------------------------------------------------------------------
    public function priv_duplicate(string $p_archive_filename)
    {
        $v_result = 1;
        // ----- Look if the $p_archive_filename exists
        if (!is_file($p_archive_filename)) {
            // ----- Nothing to duplicate, so duplicate is a success.
            $v_result = 1;
            // ----- Return
            return $v_result;
        }
        // ----- Open the zip file
        if (($v_result = $this->priv_open_fd('wb')) != 1) {
            // ----- Return
            return $v_result;
        }
        // ----- Open the temporary file in write mode
        if (($v_zip_temp_fd = @fopen($p_archive_filename, 'rb')) == 0) {
            $this->priv_close_fd();
            $this->priv_error_log(PCLZIP_ERR_READ_OPEN_FAIL, 'Unable to open archive file \'' . $p_archive_filename . '\' in binary write mode');
            // ----- Return
            return $this->error_code();
        }
        // ----- Copy the files from the archive to the temporary file
        // TBC : Here I should better append the file and go back to erase the central dir
        $v_size = filesize($p_archive_filename);
        while ($v_size != 0) {
            $v_read_size = $v_size < PCLZIP_READ_BLOCK_SIZE ? $v_size : PCLZIP_READ_BLOCK_SIZE;
            $v_buffer = fread($v_zip_temp_fd, $v_read_size);
            @fwrite($this->zip_fd, $v_buffer, $v_read_size);
            $v_size -= $v_read_size;
        }
        // ----- Close
        $this->priv_close_fd();
        // ----- Close the temporary file
        @fclose($v_zip_temp_fd);
        // ----- Return
        return $v_result;
    }
