    // Function : privErrorLog()
    // Description :
    // Parameters :
    // --------------------------------------------------------------------------------
    public function priv_error_log($p_error_code = 0, $p_error_string = ''): void
    {
        if (PCLZIP_ERROR_EXTERNAL == 1) {
            pcl_error($p_error_code, $p_error_string);
        } else {
            $this->error_code = $p_error_code;
            $this->error_string = $p_error_string;
        }
    }
    // --------------------------------------------------------------------------------
    // --------------------------------------------------------------------------------
    // Function : privErrorReset()
    // Description :
    // Parameters :
    // --------------------------------------------------------------------------------
    public function priv_error_reset(): void
    {
        if (PCLZIP_ERROR_EXTERNAL == 1) {
            pcl_error_reset();
        } else {
            $this->error_code = 0;
            $this->error_string = '';
        }
    }
