// Function : PclZipUtilPathReduction()
// Description :
// Parameters :
// Return Values :
// --------------------------------------------------------------------------------
function pcl_zip_util_path_reduction($p_dir)
{
    $v_result = '';
    // ----- Look for not empty path
    if ($p_dir != '') {
        // ----- Explode path by directory names
        $v_list = explode('/', $p_dir);
        // ----- Study directories from last to first
        $v_skip = 0;
        for ($i = sizeof($v_list) - 1; $i >= 0; $i--) {
            // ----- Look for current path
            if ($v_list[$i] == '.') {
                // ----- Ignore this directory
                // Should be the first $i=0, but no check is done
            } elseif ($v_list[$i] == '..') {
                $v_skip++;
            } elseif ($v_list[$i] == '') {
                // ----- First '/' i.e. root slash
                if ($i == 0) {
                    $v_result = '/' . $v_result;
                    if ($v_skip > 0) {
                        // ----- It is an invalid path, so the path is not modified
                        // TBC
                        $v_result = $p_dir;
                        $v_skip = 0;
                    }
                } elseif ($i == sizeof($v_list) - 1) {
                    $v_result = $v_list[$i];
                } else {
                    // ----- Ignore only the double '//' in path,
                    // but not the first and last '/'
                }
            } else if ($v_skip > 0) {
                $v_skip--;
            } else {
                $v_result = $v_list[$i] . ($i != sizeof($v_list) - 1 ? '/' . $v_result : '');
            }
        }
        // ----- Look for skip
        if ($v_skip > 0) {
            while ($v_skip > 0) {
                $v_result = '../' . $v_result;
                $v_skip--;
            }
        }
    }
    // ----- Return
    return $v_result;
}
// --------------------------------------------------------------------------------
// --------------------------------------------------------------------------------
// Function : PclZipUtilPathInclusion()
// Description :
//   This function indicates if the path $p_path is under the $p_dir tree. Or,
//   said in an other way, if the file or sub-dir $p_path is inside the dir
//   $p_dir.
//   The function indicates also if the path is exactly the same as the dir.
//   This function supports path with duplicated '/' like '//', but does not
//   support '.' or '..' statements.
// Parameters :
// Return Values :
//   0 if $p_path is not inside directory $p_dir
//   1 if $p_path is inside directory $p_dir
//   2 if $p_path is exactly the same as $p_dir
// --------------------------------------------------------------------------------
function pcl_zip_util_path_inclusion($p_dir, $p_path): int
{
    $v_result = 1;
    // ----- Look for path beginning by ./
    if ($p_dir == '.' || strlen($p_dir) >= 2 && substr($p_dir, 0, 2) == './') {
        $p_dir = pcl_zip_util_translate_win_path(getcwd(), false) . '/' . substr($p_dir, 1);
    }
    if ($p_path == '.' || strlen($p_path) >= 2 && substr($p_path, 0, 2) == './') {
        $p_path = pcl_zip_util_translate_win_path(getcwd(), false) . '/' . substr($p_path, 1);
    }
    // ----- Explode dir and path by directory separator
    $v_list_dir = explode('/', $p_dir);
    $v_list_dir_size = sizeof($v_list_dir);
    $v_list_path = explode('/', $p_path);
    $v_list_path_size = sizeof($v_list_path);
    // ----- Study directories paths
    $i = 0;
    $j = 0;
    while ($i < $v_list_dir_size && $j < $v_list_path_size && $v_result) {
        // ----- Look for empty dir (path reduction)
        if ($v_list_dir[$i] == '') {
            $i++;
            continue;
        }
        if ($v_list_path[$j] == '') {
            $j++;
            continue;
        }
        // ----- Compare the items
        if ($v_list_dir[$i] != $v_list_path[$j] && $v_list_dir[$i] != '' && $v_list_path[$j] != '') {
            $v_result = 0;
        }
        // ----- Next items
        $i++;
        $j++;
    }
    // ----- Look if everything seems to be the same
    if ($v_result) {
        // ----- Skip all the empty items
        while ($j < $v_list_path_size && $v_list_path[$j] == '') {
            $j++;
        }
        while ($i < $v_list_dir_size && $v_list_dir[$i] == '') {
            $i++;
        }
        if ($i >= $v_list_dir_size && $j >= $v_list_path_size) {
            // ----- There are exactly the same
            $v_result = 2;
        } elseif ($i < $v_list_dir_size) {
            // ----- The path is shorter than the dir
            $v_result = 0;
        }
    }
    // ----- Return
    return $v_result;
}
